fn run_window_view(args: WindowViewArgs) -> Result<WindowViewSuccess, WindowFailure> {
    let window_id = args.window_id.expect("parser guarantees --window-id");
    let (paths, base) = window_base(args.base);
    let report = AgentTaskReconciler::new(&paths)
        .reconcile()
        .map_err(|e| WindowFailure::new("window view", "window_failed", e.to_string()))?;
    let views = WindowLayoutService::new(&paths)
        .tab_view(&window_id, &report)
        .map_err(|e| window_failure("window view", e))?;
    let tabs = views.iter().map(view_tab_json).collect();
    Ok(WindowViewSuccess::new(base, window_id, tabs))
}

fn run_window_close_tab(args: WindowTabRefArgs) -> Result<WindowLayoutSuccess, WindowFailure> {
    let window_id = args.window_id.expect("parser guarantees --window-id");
    let tab_id = args.tab_id.expect("parser guarantees --tab-id");
    let (paths, base) = window_base(args.base);
    let mut closed = match WindowLayoutService::new(&paths)
        .close_tab_with_removed_preserving_global_last(&window_id, &tab_id, now_ms())
        .map_err(|e| window_failure("window close-tab", e))?
    {
        maestro_shell::GuardedWindowTabClose::Closed(closed) => closed,
        maestro_shell::GuardedWindowTabClose::GloballyLastVisible => {
            return Err(WindowFailure::new(
                "window close-tab",
                "last_visible_window",
                "keep one window open globally",
            ));
        }
    };
    if let Some(receipt) = closed.release_receipt.take() {
        // The headless command has no renderer binding, so after the graph+journal commit it may
        // make one bounded publication-aware attempt. Endpoint discovery is deliberately
        // postcommit; failure only parks the durable intent and cannot resurrect the closed tab.
        match maestro_shell::resolve_socket_path(&paths, None, &ProcessEnv) {
            Ok(socket_path) => {
                let _ = attempt_owned_session_release_now(
                    &paths,
                    &socket_path,
                    receipt,
                    "window close-tab",
                );
            }
            Err(error) => {
                eprintln!(
                    "window close-tab: daemon endpoint unavailable after commit; exact release remains queued: {error}"
                );
                park_owned_session_release(&paths, receipt, "window close-tab");
            }
        }
    } else if !closed.unresolved_release_session_ids.is_empty() {
        eprintln!(
            "window close-tab: committed a safe leak for unresolved PTY generations: {:?}",
            closed.unresolved_release_session_ids
        );
    }
    Ok(layout_success("window close-tab", base, closed.layout))
}

