fn run_window_attention(args: WindowAttentionArgs) -> Result<WindowLayoutSuccess, WindowFailure> {
    let window_id = args.window_id.expect("parser guarantees --window-id");
    let tab_id = args.tab_id.expect("parser guarantees --tab-id");
    let attention = attention_from_str(&args.attention.expect("parser guarantees --attention"));
    let unseen = args.unseen.expect("parser guarantees --unseen");
    // Parser already validated the source string; absent means default `process`.
    let source = args
        .source
        .as_deref()
        .map(attention_source_from_str)
        .unwrap_or(AttentionSource::Process);
    let since_ms = args.since_ms.unwrap_or_else(now_ms);
    let state = AttentionState {
        attention,
        unseen,
        since_ms,
        source,
    };
    let (paths, base) = window_base(args.base);
    let layout = WindowLayoutService::new(&paths)
        .update_attention(&window_id, &tab_id, state, now_ms())
        .map_err(|e| window_failure("window attention", e))?;
    Ok(layout_success("window attention", base, layout))
}

/// Clear a tab's persisted attention to the seen/none user-cleared state, returning the same
/// `WindowLayoutSuccess` shape as `window attention`. Writes a fixed `AttentionState`
/// (`none`/`unseen:false`/`source:user`) through the existing `update_attention` path.
fn run_window_attention_clear(
    args: WindowTabRefArgs,
) -> Result<WindowLayoutSuccess, WindowFailure> {
    let window_id = args.window_id.expect("parser guarantees --window-id");
    let tab_id = args.tab_id.expect("parser guarantees --tab-id");
    let state = AttentionState {
        attention: Attention::None,
        unseen: false,
        since_ms: now_ms(),
        source: AttentionSource::User,
    };
    let (paths, base) = window_base(args.base);
    let layout = WindowLayoutService::new(&paths)
        .update_attention(&window_id, &tab_id, state, now_ms())
        .map_err(|e| window_failure("window attention-clear", e))?;
    Ok(layout_success("window attention-clear", base, layout))
}

/// Map a parser-validated `--attention` wire string back to [`Attention`]. The parser only ever
/// passes one of these five, so an unexpected value is an internal invariant break.
fn attention_from_str(raw: &str) -> Attention {
    match raw {
        "none" => Attention::None,
        "activity" => Attention::Activity,
        "needs_input" => Attention::NeedsInput,
        "error" => Attention::Error,
        "done" => Attention::Done,
        other => unreachable!("parser guarantees a valid --attention value, got {other:?}"),
    }
}

/// Map a parser-validated `--source` wire string back to [`AttentionSource`].
fn attention_source_from_str(raw: &str) -> AttentionSource {
    match raw {
        "process" => AttentionSource::Process,
        "agent" => AttentionSource::Agent,
        "user" => AttentionSource::User,
        other => unreachable!("parser guarantees a valid --source value, got {other:?}"),
    }
}

/// Map a [`WindowLayoutError`] to the app's stable `window_failed` failure DTO. Raw shell errors are
/// never surfaced as JSON directly; only their `Display` message is carried.
fn window_failure(command: &'static str, err: WindowLayoutError) -> WindowFailure {
    WindowFailure::new(command, "window_failed", err.to_string())
}

/// Shape a persisted [`WindowLayout`] into a [`WindowLayoutSuccess`] with ordered tabs (each tab
/// carries its attention object).
fn layout_success(
    command: &'static str,
    base: String,
    layout: WindowLayout,
) -> WindowLayoutSuccess {
    let tabs = layout.tabs.iter().map(tab_json).collect();
    WindowLayoutSuccess::new(command, base, layout.window_id, tabs)
}

/// Shape one persisted [`TabRecord`] into its JSON DTO.
fn tab_json(tab: &TabRecord) -> WindowTabJson {
    WindowTabJson {
        tab_id: tab.tab_id.clone(),
        session_id: tab.session_id.clone(),
        index: tab.index,
        title: tab.title.clone(),
        pinned: tab.pinned,
        attention: attention_json(&tab.attention),
        split_from: tab.split_from.as_ref().map(|s| SplitFromJson {
            tab_id: s.tab_id.clone(),
            axis: match s.axis {
                SplitAxis::Right => "right".to_string(),
                SplitAxis::Down => "down".to_string(),
            },
            ratio_per_mille: s.ratio_per_mille,
        }),
        pane_rect: tab.pane_rect.as_ref().map(|r| PaneRectJson {
            x: r.x,
            y: r.y,
            w: r.w,
            h: r.h,
        }),
    }
}

/// Shape one projected [`WindowTabView`] row into its JSON DTO, carrying the joined task/session
/// fields plus the persisted layout/attention fields.
fn view_tab_json(view: &WindowTabView) -> WindowViewTabJson {
    WindowViewTabJson {
        tab_id: view.tab_id.clone(),
        session_id: view.session_id.clone(),
        index: view.index,
        title: view.title.clone(),
        pinned: view.pinned,
        attention: attention_json(&view.attention),
        session_status: view.session_status.map(|s| status_str(s).to_string()),
        agent_task_id: view.agent_task_id.clone(),
        agent_task_state: view
            .agent_task_state
            .map(|s| agent_state_str(s).to_string()),
        needs_attention: view.needs_attention,
        session_record_missing: view.session_record_missing,
        split_from: view.split_from.as_ref().map(|s| SplitFromJson {
            tab_id: s.tab_id.clone(),
            axis: match s.axis {
                SplitAxis::Right => "right".to_string(),
                SplitAxis::Down => "down".to_string(),
            },
            ratio_per_mille: s.ratio_per_mille,
        }),
        // Carry the AUTHORITATIVE pane rect from the view join so the periodic live refresh paints from
        // rects, not the legacy split_from chain (the cause of the ~750ms "snap to another shape").
        pane_rect: view.pane_rect.as_ref().map(|r| PaneRectJson {
            x: r.x,
            y: r.y,
            w: r.w,
            h: r.h,
        }),
        stashed: view.stashed,
    }
}

/// Shape a persisted [`AttentionState`] into its JSON DTO with the wire-stable snake_case strings.
fn attention_json(attention: &AttentionState) -> AttentionJson {
    AttentionJson {
        attention: attention_str(attention.attention).to_string(),
        unseen: attention.unseen,
        since_ms: attention.since_ms,
        source: attention_source_str(attention.source).to_string(),
    }
}

/// The wire-stable string for a [`SessionStatus`], matching its serde `snake_case` repr.
fn status_str(status: SessionStatus) -> &'static str {
    match status {
        SessionStatus::Live => "live",
        SessionStatus::Exited => "exited",
        SessionStatus::Unknown => "unknown",
    }
}

/// The wire-stable string for an [`AgentTaskState`], matching its serde `snake_case` repr.
fn agent_state_str(state: AgentTaskState) -> &'static str {
    match state {
        AgentTaskState::Draft => "draft",
        AgentTaskState::Running => "running",
        AgentTaskState::WaitingOnUser => "waiting_on_user",
        AgentTaskState::Blocked => "blocked",
        AgentTaskState::Succeeded => "succeeded",
        AgentTaskState::Failed => "failed",
        AgentTaskState::Cancelled => "cancelled",
    }
}

/// The wire-stable string for an [`Attention`], matching its serde `snake_case` repr.
fn attention_str(attention: Attention) -> &'static str {
    match attention {
        Attention::None => "none",
        Attention::Activity => "activity",
        Attention::NeedsInput => "needs_input",
        Attention::Error => "error",
        Attention::Done => "done",
    }
}

/// The wire-stable string for an [`AttentionSource`], matching its serde `snake_case` repr.
fn attention_source_str(source: AttentionSource) -> &'static str {
    match source {
        AttentionSource::Process => "process",
        AttentionSource::Agent => "agent",
        AttentionSource::User => "user",
    }
}

fn dashboard_react_model(paths: &AppPaths) -> serde_json::Value {
    dashboard_react_model_with_active(paths, None, None)
}

#[cfg(target_os = "macos")]
const DESKTOP_ACCESS_UNINITIALIZED: u8 = 0;
#[cfg(target_os = "macos")]
const DESKTOP_ACCESS_GRANTED: u8 = 1;
#[cfg(target_os = "macos")]
const DESKTOP_ACCESS_REQUIRED: u8 = 2;
#[cfg(target_os = "macos")]
const DESKTOP_ACCESS_UNKNOWN: u8 = 3;

#[cfg(target_os = "macos")]
static DESKTOP_ACCESS_STATUS: AtomicU8 = AtomicU8::new(DESKTOP_ACCESS_UNINITIALIZED);

#[cfg(target_os = "macos")]
fn desktop_access_status_from_u8(value: u8) -> Option<DesktopAccessStatus> {
    match value {
        DESKTOP_ACCESS_GRANTED => Some(DesktopAccessStatus::Granted),
        DESKTOP_ACCESS_REQUIRED => Some(DesktopAccessStatus::Required),
        DESKTOP_ACCESS_UNKNOWN => Some(DesktopAccessStatus::Unknown),
        _ => None,
    }
}

#[cfg(target_os = "macos")]
fn desktop_access_status_to_u8(status: DesktopAccessStatus) -> u8 {
    match status {
        DesktopAccessStatus::Granted => DESKTOP_ACCESS_GRANTED,
        DesktopAccessStatus::Required => DESKTOP_ACCESS_REQUIRED,
        DesktopAccessStatus::Unknown | DesktopAccessStatus::NotApplicable => DESKTOP_ACCESS_UNKNOWN,
    }
}

/// Perform a fresh capability probe. Persisted onboarding state never contributes to `status`.
#[cfg(target_os = "macos")]
fn refresh_desktop_access_status(paths: &AppPaths) -> DesktopAccessStatus {
    let status = maestro_shell::desktop_access::current_status();
    DESKTOP_ACCESS_STATUS.store(desktop_access_status_to_u8(status), Ordering::Release);
    if status == DesktopAccessStatus::Granted
        && !maestro_app::desktop_access_onboarding::onboarding_acknowledged(paths)
    {
        if let Err(error) =
            maestro_app::desktop_access_onboarding::acknowledge_onboarding(paths, now_ms())
        {
            eprintln!(
                "desktop access: could not persist non-authoritative acknowledgement: {error}"
            );
        }
    }
    status
}

#[cfg(target_os = "macos")]
fn cached_desktop_access_status(paths: &AppPaths) -> DesktopAccessStatus {
    desktop_access_status_from_u8(DESKTOP_ACCESS_STATUS.load(Ordering::Acquire))
        .unwrap_or_else(|| refresh_desktop_access_status(paths))
}

#[cfg(target_os = "macos")]
fn desktop_access_dashboard_value(paths: &AppPaths) -> serde_json::Value {
    maestro_app::desktop_access_onboarding::dashboard_value(
        cached_desktop_access_status(paths),
        maestro_app::desktop_access_onboarding::onboarding_acknowledged(paths),
    )
}

#[cfg(target_os = "macos")]
fn open_full_disk_access_settings() -> bool {
    use maestro_app::desktop_access_onboarding::{
        FULL_DISK_ACCESS_SETTINGS_URL, LEGACY_FULL_DISK_ACCESS_SETTINGS_URL,
        SYSTEM_SETTINGS_BUNDLE_ID,
    };

    for url in [
        FULL_DISK_ACCESS_SETTINGS_URL,
        LEGACY_FULL_DISK_ACCESS_SETTINGS_URL,
    ] {
        if ProcCommand::new("/usr/bin/open")
            .arg(url)
            .status()
            .is_ok_and(|status| status.success())
        {
            return true;
        }
    }
    ProcCommand::new("/usr/bin/open")
        .args(["-b", SYSTEM_SETTINGS_BUNDLE_ID])
        .status()
        .is_ok_and(|status| status.success())
}

fn dashboard_react_model_with_active(
    paths: &AppPaths,
    active_window_id: Option<&str>,
    active_tab_id: Option<&str>,
) -> serde_json::Value {
    dashboard_react_model_with_active_and_report(paths, active_window_id, active_tab_id, None)
}

fn dashboard_react_model_with_active_and_report(
    paths: &AppPaths,
    active_window_id: Option<&str>,
    active_tab_id: Option<&str>,
    session_report: Option<&maestro_shell::ReconcileReport>,
) -> serde_json::Value {
    let mut model = match DashboardSnapshotService::new(paths).snapshot(session_report) {
        Ok(mut snapshot) => {
            let order = maestro_app::apply_window_presentation_order(paths, &mut snapshot);
            let session_agents = session_agent_index(paths);
            let mut model =
                dashboard_react_model_from_snapshot_with_sessions(&snapshot, &session_agents);
            // Presentation order must not expose unassigned/recovery identities that the
            // ordinary project projection intentionally keeps native-only.
            let visible_ids: std::collections::HashSet<&str> = snapshot
                .projects
                .iter()
                .filter(|project| project.project_id != PRODUCT_RECOVERY_PROJECT_ID)
                .flat_map(|project| project.windows.iter())
                .map(|window| window.window_id.as_str())
                .collect();
            model["global_window_order"] = serde_json::json!(order
                .into_iter()
                .filter(|id| visible_ids.contains(id.as_str()))
                .collect::<Vec<_>>());
            model
        }
        Err(err) => {
            eprintln!("hydra-dashboard snapshot failed: {err}");
            empty_dashboard_react_model()
        }
    };
    if let serde_json::Value::Object(ref mut object) = model {
        let remote = maestro_app::optional_extension::current_projection();
        object.insert(
            "active_window_id".to_string(),
            active_window_id
                .map(str::to_string)
                .map(serde_json::Value::String)
                .unwrap_or(serde_json::Value::Null),
        );
        object.insert(
            "active_tab_id".to_string(),
            active_tab_id
                .map(str::to_string)
                .map(serde_json::Value::String)
                .unwrap_or(serde_json::Value::Null),
        );
        object.insert(
            "remote_open".to_string(),
            serde_json::Value::Bool(remote.available && remote.remote_open),
        );
        object.insert(
            "remote_available".to_string(),
            serde_json::Value::Bool(remote.available),
        );
        // Cached stable model catalog: the chrome merges these lists
        // over its built-in per-agent dropdowns; Null/absent → built-ins only.
        object.insert(
            "model_catalog".to_string(),
            maestro_app::model_catalog::load_cached(
                &paths
                    .base()
                    .join(maestro_app::model_catalog::cache_filename()),
            )
            .unwrap_or(serde_json::Value::Null),
        );
        object.insert(
            "update".to_string(),
            serde_json::to_value(maestro_app::update_check::dashboard_model())
                .expect("desktop update dashboard state serializes"),
        );
        object.insert(
            "enrolled".to_string(),
            serde_json::Value::Bool(remote.available && remote.enrolled),
        );
        object.insert(
            "filesystem_mode_migration".to_string(),
            filesystem_mode_migration_dashboard_value(&remote),
        );
        object.insert(
            "account_id".to_string(),
            remote
                .account_id
                .map(serde_json::Value::String)
                .unwrap_or(serde_json::Value::Null),
        );
        #[cfg(target_os = "macos")]
        object.insert(
            "desktop_access".to_string(),
            desktop_access_dashboard_value(paths),
        );
    }
    model
}

fn filesystem_mode_migration_dashboard_value(
    projection: &maestro_app::optional_extension::RemoteExtensionProjection,
) -> serde_json::Value {
    let Some(notice) = projection.filesystem_mode_migration.as_ref() else {
        return serde_json::Value::Null;
    };
    let mut value = serde_json::to_value(notice)
        .expect("validated filesystem-mode migration notice serializes");
    let Some(changes) = value
        .as_object_mut()
        .and_then(|object| object.get_mut("changes"))
        .and_then(serde_json::Value::as_array_mut)
    else {
        unreachable!("validated migration notice serializes a changes array")
    };
    for (change_value, change) in changes.iter_mut().zip(notice.changes()) {
        let object = change_value
            .as_object_mut()
            .expect("validated migration change serializes as an object");
        object.insert(
            "rollback_command".to_string(),
            serde_json::Value::String(change.rollback_command()),
        );
    }
    value
}

fn dashboard_react_model_from_snapshot_with_sessions(
    snapshot: &DashboardSnapshot,
    session_agents: &std::collections::HashMap<String, &'static str>,
) -> serde_json::Value {
    let view = build_dashboard_view_model(snapshot);
    let mut model = serde_json::to_value(&view).expect("DashboardViewModel serializes");
    let details = snapshot
        .projects
        .iter()
        .filter(|project| project.project_id != PRODUCT_RECOVERY_PROJECT_ID)
        .map(|project| {
            (
                project.project_id.clone(),
                dashboard_react_project_detail(project, session_agents),
            )
        })
        .collect::<serde_json::Map<String, serde_json::Value>>();

    if let serde_json::Value::Object(ref mut object) = model {
        object.insert("details".to_string(), serde_json::Value::Object(details));
        // Reconciliation ids stay native-only. The React dashboard is the ownership surface, not
        // an orphan-classification console; automatic cleanup consumes the complete native
        // snapshot directly and no recovered id crosses the WebView boundary.
        object.insert(
            "recovered_sessions".to_string(),
            serde_json::Value::Array(Vec::new()),
        );
    }
    model
}

fn session_agent_index(paths: &AppPaths) -> std::collections::HashMap<String, &'static str> {
    load_all::<SessionRecord>(paths, RecordKind::Session)
        .map(|outcomes| {
            outcomes
                .into_iter()
                .filter_map(|outcome| match outcome {
                    LoadOutcome::Loaded(record) => {
                        agent_history::agent_from_session_record(&record)
                            .map(|agent| (record.session_id, agent))
                    }
                    LoadOutcome::Quarantined { .. } | LoadOutcome::FutureVersion { .. } => None,
                })
                .collect()
        })
        .unwrap_or_default()
}

fn empty_dashboard_react_model() -> serde_json::Value {
    serde_json::json!({
        "active_project": null,
        "projects": [],
        "counts": {
            "draft": 0,
            "running": 0,
            "waiting_on_user": 0,
            "blocked": 0,
            "succeeded": 0,
            "failed": 0,
            "cancelled": 0
        },
        "attention_count": 0,
        "active_tasks": [],
        "details": {},
        "recovered_sessions": [],
        "active_window_id": null,
        "active_tab_id": null,
        "filesystem_mode_migration": null,
        "update": maestro_app::update_check::dashboard_model()
    })
}

fn dashboard_react_project_detail(
    project: &maestro_shell::ProjectSnapshot,
    session_agents: &std::collections::HashMap<String, &'static str>,
) -> serde_json::Value {
    let windows = project
        .windows
        .iter()
        .map(|window| dashboard_react_window(window, session_agents))
        .collect::<Vec<_>>();
    let tasks = project
        .tasks
        .iter()
        .map(|task| {
            serde_json::json!({
                "agent_task_id": task.agent_task_id,
                "project_id": task.project_id,
                "goal": task.goal,
                "state": agent_state_str(task.state),
                "current_session_id": task.current_session_id,
                "updated_at_ms": task.updated_at_ms,
                "result_summary": task.result_summary,
            })
        })
        .collect::<Vec<_>>();

    serde_json::json!({
        "project_id": project.project_id,
        "name": project.name,
        "root": project.root,
        "icon": project.icon,
        "accent_color": project.accent_color,
        "launch_defaults": project.launch_defaults,
        "extra_folders": project.directories,
        "default_workspace_policy": project.default_workspace_policy,
        "last_active_at_ms": project.last_active_at_ms,
        // The built-in "Terminal" project (system) + user-hidden flag — the React chrome uses these to simplify its
        // dialogs (Terminal: rename/color/icon only, no agent/folder) + refuse delete.
        "system": project.system,
        "hidden": project.hidden,
        "windows": windows,
        "tasks": tasks,
    })
}

fn dashboard_react_window(
    window: &maestro_shell::DashboardWindow,
    session_agents: &std::collections::HashMap<String, &'static str>,
) -> serde_json::Value {
    let tabs = window
        .tabs
        .iter()
        .map(|tab| dashboard_react_tab(tab, session_agents))
        .collect::<Vec<_>>();
    let stashed = !window.tabs.is_empty() && window.tabs.iter().all(|tab| tab.stashed);
    serde_json::json!({
        "window_id": window.window_id,
        "name": window.name,
        "root": null,
        "stashed": stashed,
        "tabs": tabs,
    })
}

fn dashboard_react_tab(
    tab: &maestro_shell::DashboardTab,
    session_agents: &std::collections::HashMap<String, &'static str>,
) -> serde_json::Value {
    serde_json::json!({
        "window_id": tab.window_id,
        "tab_id": tab.tab_id,
        "session_id": tab.session_id,
        "index": tab.index,
        "title": tab.title,
        "pinned": tab.pinned,
        "attention": attention_str(tab.attention.attention),
        "agent_task_id": tab.agent_task_id,
        "agent_task_state": tab.agent_task_state.map(agent_state_str),
        "session_status": tab.session_status.map(status_str),
        "session_record_missing": tab.session_record_missing,
        "needs_attention": tab.needs_attention,
        "stashed": tab.stashed,
        "cwd": tab.cwd,
        "agent": dashboard_agent_from_tab(tab, session_agents),
    })
}

fn dashboard_agent_from_tab(
    tab: &maestro_shell::DashboardTab,
    session_agents: &std::collections::HashMap<String, &'static str>,
) -> &'static str {
    if let Some(agent) = session_agents.get(&tab.session_id) {
        return agent;
    }
    let haystack = format!(
        "{} {} {}",
        tab.title.to_ascii_lowercase(),
        tab.tab_id.to_ascii_lowercase(),
        tab.session_id.to_ascii_lowercase()
    );
    if haystack.contains("claude") {
        "claude"
    } else if haystack.contains("codex") {
        "codex"
    } else if haystack.contains("copilot") {
        "copilot"
    } else if haystack.contains("antigravity") {
        "antigravity"
    } else if haystack.contains("kimi") {
        "kimi"
    } else if haystack.contains("kiro") {
        "kiro"
    } else if haystack.contains("cursor") {
        "cursor"
    } else if haystack.contains("gemini") {
        "gemini"
    } else {
        "shell"
    }
}

fn renderer_react_chrome(paths: &AppPaths) -> Option<maestro_renderer::RendererReactChrome> {
    // The React dashboard chrome (sidebar/topbar/overlay assets + host bridge) is enabled on EVERY desktop
    // platform. The asset resolver is platform-neutral (dashboard_ui_asset_candidates resolves both the macOS
    // Contents/Resources layout AND the Linux packaged <root>/dashboard-ui layout), so the same code path
    // drives both. macOS behavior is unchanged — this is the identical body that was `#[cfg(target_os="macos")]`,
    // now also compiled for Linux where it previously short-circuited to `None`.
    {
        let current_exe = match std::env::current_exe() {
            Ok(path) => path,
            Err(err) => {
                eprintln!("hydra-dashboard current_exe failed: {err}");
                return None;
            }
        };
        // Debug builds may use the development-tree asset fallback, derived at runtime from the
        // executable location (`<repo>/target/{debug,release}`). Production builds do not derive or
        // inspect a repo/CWD path; the resolver also enforces its bundled-only policy independently.
        #[cfg(debug_assertions)]
        let repo_root = current_exe
            .ancestors()
            .find(|dir| dir.file_name().is_some_and(|name| name == "target"))
            .and_then(Path::parent)
            .map(Path::to_path_buf)
            .unwrap_or_else(|| PathBuf::from("."));
        #[cfg(not(debug_assertions))]
        let repo_root = PathBuf::new();
        let repo_root = repo_root.as_path();
        let candidates = dashboard_ui_asset_candidates(None, &current_exe, repo_root);
        #[cfg(debug_assertions)]
        eprintln!(
            "hydra-dashboard asset candidates current_exe={} app_bundle={} app_bundle_exists={} dev_repo={} dev_repo_exists={}",
            current_exe.display(),
            candidates.app_bundle.display(),
            candidates.app_bundle.is_file(),
            candidates.dev_repo.display(),
            candidates.dev_repo.is_file()
        );
        #[cfg(not(debug_assertions))]
        eprintln!(
            "hydra-dashboard bundled asset candidate current_exe={} app_bundle={} app_bundle_exists={}",
            current_exe.display(),
            candidates.app_bundle.display(),
            candidates.app_bundle.is_file()
        );
        let Some(asset) = resolve_dashboard_ui_asset(None, &current_exe, repo_root) else {
            #[cfg(debug_assertions)]
            eprintln!(
                "hydra-dashboard asset not found current_exe={} repo_root={}",
                current_exe.display(),
                repo_root.display()
            );
            #[cfg(not(debug_assertions))]
            eprintln!(
                "hydra-dashboard bundled asset not found current_exe={} app_bundle={}",
                current_exe.display(),
                candidates.app_bundle.display()
            );
            return None;
        };
        eprintln!(
            "hydra-dashboard asset selected source={:?} index={}",
            asset.source,
            asset.index_html.display()
        );
        let model = dashboard_react_model(paths);
        let initialization_script = dashboard_ui_host_preload_script(
            &model,
            // Intent delivery: prefer the native IPC bridge (window.ipc / webkit.messageHandlers.ipc). The
            // `#hydra-intent:` navigation-URL fallback is a LAST RESORT — only used when NEITHER IPC bridge is
            // present — because mutating `location.href` puts an encoded-JSON fragment on the page URL, and on
            // WebKitGTK wry's IPC handler reads `webview.uri().unwrap()` which PANICS on that non-URI fragment
            // (wry mod.rs:648). Guarding the fallback behind `if (!delivered)` keeps the URL fragment-free
            // whenever native IPC works (both platforms), so wry never sees an invalid URI. macOS is unaffected
            // (its WKWebView IPC already delivered, so the fallback never ran there either).
            "(function (intent) { var message = JSON.stringify(intent); var delivered = false; try { if (window.ipc && window.ipc.postMessage) { window.ipc.postMessage(message); delivered = true; } } catch (_) {} try { if (!delivered && window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.ipc) { window.webkit.messageHandlers.ipc.postMessage(message); delivered = true; } } catch (_) {} if (!delivered) { try { var base = String(window.location.href || '').split('#')[0]; window.location.href = base + '#hydra-intent:' + encodeURIComponent(message); delivered = true; } catch (_) {} } if (!delivered) { (window.__HYDRA_DASHBOARD_INTENTS__ = window.__HYDRA_DASHBOARD_INTENTS__ || []).push(intent); } })",
        );
        let url = dashboard_ui_file_url(&asset.index_html, Some("chrome=sidebar"));
        let top_url = dashboard_ui_file_url(&asset.index_html, Some("chrome=topbar"));
        let overlay_url = dashboard_ui_file_url(&asset.index_html, Some("chrome=overlay"));
        eprintln!(
            "hydra-dashboard react chrome enabled url={url} top_url={top_url} overlay_url={overlay_url}"
        );
        Some(maestro_renderer::RendererReactChrome {
            url,
            top_url,
            overlay_url,
            initialization_script,
            width_logical_px: 460,
            top_height_logical_px: 46,
        })
    }
}

fn refresh_react_chrome_dashboard(
    paths: &AppPaths,
    tab_runtime: &mut RendererTabRuntime,
    context: &str,
) {
    refresh_react_chrome_dashboard_with_focused(paths, tab_runtime, None, context);
}

/// Deliver completed provider-history reads only after the listener has first had a chance to
/// consume queued renderer intents. Native request ownership filters stale results here; the
/// dashboard's request map remains the final guard for the irreducible cross-channel race where a
/// modal closes just after an idle tick begins.
fn deliver_history_results(
    history_discovery: &mut history_discovery::HistoryDiscovery,
    tab_runtime: &mut RendererTabRuntime,
) {
    for result in history_discovery.take_ready() {
        let (request_id, script, summary) = match result {
            history_discovery::HistoryResult::FolderSessions {
                request_id,
                sessions,
            } => {
                let request_json =
                    serde_json::to_string(&request_id).expect("request id serializes");
                let sessions_json = serde_json::to_string(&sessions).expect("sessions serialize");
                let count = sessions.len();
                (
                    request_id,
                    format!(
                        "if (window.__HYDRA_DASHBOARD_RESOLVE_FOLDER_SESSIONS__) {{ window.__HYDRA_DASHBOARD_RESOLVE_FOLDER_SESSIONS__({request_json}, {sessions_json}); }}"
                    ),
                    format!("folder sessions count={count}"),
                )
            }
            history_discovery::HistoryResult::HiddenSessions {
                request_id,
                sessions,
            } => {
                let request_json =
                    serde_json::to_string(&request_id).expect("request id serializes");
                let sessions_json = serde_json::to_string(&sessions).expect("sessions serialize");
                let count = sessions.len();
                (
                    request_id,
                    format!(
                        "if (window.__HYDRA_DASHBOARD_RESOLVE_HIDDEN_SESSIONS__) {{ window.__HYDRA_DASHBOARD_RESOLVE_HIDDEN_SESSIONS__({request_json}, {sessions_json}); }}"
                    ),
                    format!("hidden sessions count={count}"),
                )
            }
            history_discovery::HistoryResult::SessionMutation {
                request_id,
                ok,
                sessions,
            } => {
                let request_json =
                    serde_json::to_string(&request_id).expect("request id serializes");
                let ok_json = serde_json::to_string(&ok).expect("bool serializes");
                let sessions_json = serde_json::to_string(&sessions).expect("sessions serialize");
                let count = sessions.len();
                (
                    request_id,
                    format!(
                        "if (window.__HYDRA_DASHBOARD_RESOLVE_SESSION_NAME__) {{ window.__HYDRA_DASHBOARD_RESOLVE_SESSION_NAME__({request_json}, {ok_json}, {sessions_json}); }}"
                    ),
                    format!("session mutation ok={ok} visible_count={count}"),
                )
            }
            history_discovery::HistoryResult::Preview { request_id, lines } => {
                let request_json =
                    serde_json::to_string(&request_id).expect("request id serializes");
                let lines_json = serde_json::to_string(&lines).expect("preview lines serialize");
                let count = lines.len();
                (
                    request_id,
                    format!(
                        "if (window.__HYDRA_DASHBOARD_RESOLVE_SESSION_PREVIEW__) {{ window.__HYDRA_DASHBOARD_RESOLVE_SESSION_PREVIEW__({request_json}, {lines_json}); }}"
                    ),
                    format!("preview lines={count}"),
                )
            }
        };
        if let Err(error) = tab_runtime.evaluate_react_chrome_script(script) {
            eprintln!(
                "attach-tab: React agent-history response failed request={request_id:?} (non-fatal): {error}"
            );
        } else {
            eprintln!("attach-tab: React agent-history response request={request_id:?} {summary}");
        }
    }
}

fn live_tab_id_in_window(paths: &AppPaths, window_id: &str, tab_id: &str) -> Option<String> {
    let layout = WindowLayoutService::new(paths).load(window_id).ok()??;
    layout
        .tabs
        .into_iter()
        .find(|tab| tab.tab_id == tab_id && !tab.stashed)
        .map(|tab| tab.tab_id)
}

fn listener_new_tab_snapshot(
    paths: &AppPaths,
    context: ListenerWindowContext,
    window_id: &str,
    live_strip_tabs: &[WindowTabJson],
    active_tab_id: Option<&str>,
) -> Result<maestro_app::NewTabSnapshot, String> {
    if !context.is_bound() {
        return Ok(maestro_app::new_tab_snapshot_from_strip_tabs(
            live_strip_tabs,
            active_tab_id,
        ));
    }
    let layout = WindowLayoutService::new(paths)
        .load(window_id)
        .map_err(|error| {
            format!("could not load target window {window_id:?} for identity reservation: {error}")
        })?
        .ok_or_else(|| {
            format!("target window {window_id:?} disappeared before identity reservation")
        })?;
    Ok(maestro_app::new_tab_snapshot_from_tab_records(
        &layout.tabs,
        active_tab_id,
    ))
}

fn listener_window_containing_live_tabs(
    paths: &AppPaths,
    listener_window_id: &str,
    emitted_window_id: &str,
    tab_ids: &[&str],
) -> Option<String> {
    if emitted_window_id != listener_window_id {
        return None;
    }
    let contains_all = |layout: &WindowLayout| {
        tab_ids.iter().all(|tab_id| {
            layout
                .tabs
                .iter()
                .any(|tab| tab.tab_id == *tab_id && !tab.stashed)
        })
    };
    if WindowLayoutService::new(paths)
        .load(listener_window_id)
        .ok()
        .flatten()
        .as_ref()
        .is_some_and(contains_all)
    {
        return Some(listener_window_id.to_string());
    }
    None
}

fn refresh_react_chrome_dashboard_with_focused(
    paths: &AppPaths,
    tab_runtime: &mut RendererTabRuntime,
    focused_tab_id: Option<&str>,
    context: &str,
) {
    if tab_runtime.pending_viewport().is_some() {
        eprintln!(
            "hydra-dashboard refresh after {context} deferred until exact viewport publication"
        );
        return;
    }
    let focused_live_tab_id = match (tab_runtime.active_window_id(), focused_tab_id) {
        (Some(window_id), Some(tab_id)) => live_tab_id_in_window(paths, window_id, tab_id),
        _ => None,
    };
    let model = dashboard_react_model_with_active(
        paths,
        tab_runtime.active_window_id(),
        focused_live_tab_id
            .as_deref()
            .or_else(|| tab_runtime.active_tab_id()),
    );
    if let Err(err) = tab_runtime.set_react_chrome_model(&model) {
        eprintln!("hydra-dashboard refresh after {context} failed (non-fatal): {err}");
    }
}

/// Refresh the dashboard model like [`refresh_react_chrome_dashboard_with_focused`], but also stamp a one-shot
/// `enroll_error` into the model so the sidebar can show why an "Add Remote" attempt failed (e.g. expired code).
/// `None` clears any prior error. Used only by the enrollDesktop intent; other refreshes leave enroll_error absent.
fn refresh_react_chrome_dashboard_with_enroll_error(
    paths: &AppPaths,
    tab_runtime: &mut RendererTabRuntime,
    focused_tab_id: Option<&str>,
    context: &str,
    enroll_error: Option<&str>,
) {
    let focused_live_tab_id = match (tab_runtime.active_window_id(), focused_tab_id) {
        (Some(window_id), Some(tab_id)) => live_tab_id_in_window(paths, window_id, tab_id),
        _ => None,
    };
    let mut model = dashboard_react_model_with_active(
        paths,
        tab_runtime.active_window_id(),
        focused_live_tab_id
            .as_deref()
            .or_else(|| tab_runtime.active_tab_id()),
    );
    if let serde_json::Value::Object(ref mut object) = model {
        object.insert(
            "enroll_error".to_string(),
            match enroll_error {
                Some(msg) => serde_json::Value::String(msg.to_string()),
                None => serde_json::Value::Null,
            },
        );
    }
    if let Err(err) = tab_runtime.set_react_chrome_model(&model) {
        eprintln!("hydra-dashboard refresh after {context} failed (non-fatal): {err}");
    }
}

fn project_optional_extension(
    tab_runtime: &mut RendererTabRuntime,
    projection: &maestro_app::optional_extension::RemoteExtensionProjection,
) {
    let (available, remote_open, remote_winsize, remote_owned_sessions) =
        optional_extension_renderer_projection(projection);
    let _ = tab_runtime.set_remote_extension_state(
        available,
        remote_open,
        remote_winsize,
        remote_owned_sessions,
    );
}

fn optional_extension_renderer_projection(
    projection: &maestro_app::optional_extension::RemoteExtensionProjection,
) -> (bool, bool, bool, Vec<String>) {
    let available = projection.available && projection.filesystem_mode_migration.is_none();
    (
        available,
        available && projection.remote_open,
        available && projection.remote_winsize(),
        if available {
            projection.remote_owned_sessions.clone()
        } else {
            Vec::new()
        },
    )
}

fn drain_optional_extension_updates(
    worker: &maestro_app::optional_extension::OptionalExtensionWorker,
    last_projection: &mut maestro_app::optional_extension::RemoteExtensionProjection,
    paths: &AppPaths,
    tab_runtime: &mut RendererTabRuntime,
    focused_tab_id: Option<&str>,
) {
    while let Some(update) = worker.try_recv() {
        let projection_changed = update.projection != *last_projection;
        maestro_app::optional_extension::publish_projection(&update.projection);
        project_optional_extension(tab_runtime, &update.projection);
        *last_projection = update.projection;

        let operation_completed =
            update.operation != maestro_app::optional_extension::ExtensionOperation::Refresh;
        if !(projection_changed || operation_completed) {
            continue;
        }
        if update.operation == maestro_app::optional_extension::ExtensionOperation::Enroll {
            refresh_react_chrome_dashboard_with_enroll_error(
                paths,
                tab_runtime,
                focused_tab_id,
                "optionalExtensionEnroll",
                update.error_message,
            );
        } else {
            if let Some(message) = update.error_message {
                eprintln!("attach-tab: optional extension operation failed: {message}");
            }
            refresh_react_chrome_dashboard_with_focused(
                paths,
                tab_runtime,
                focused_tab_id,
                "optionalExtensionState",
            );
        }
    }
}

fn project_id_from_name(name: &str, now_ms: u64) -> String {
    let mut slug = String::new();
    let mut last_was_dash = false;
    for ch in name.chars().flat_map(char::to_lowercase) {
        if ch.is_ascii_alphanumeric() {
            slug.push(ch);
            last_was_dash = false;
        } else if !last_was_dash && !slug.is_empty() {
            slug.push('-');
            last_was_dash = true;
        }
        if slug.len() >= 48 {
            break;
        }
    }
    while slug.ends_with('-') {
        slug.pop();
    }
    if slug.is_empty() {
        slug.push_str("project");
    }
    format!("{slug}-{now_ms}")
}

fn normalize_project_root(root: &str) -> String {
    let trimmed = root.trim();
    if trimmed == "~" {
        std::env::var("HOME").unwrap_or_else(|_| trimmed.to_string())
    } else if let Some(rest) = trimmed.strip_prefix("~/") {
        match std::env::var("HOME") {
            Ok(home) => format!("{home}/{rest}"),
            Err(_) => trimmed.to_string(),
        }
    } else {
        trimmed.to_string()
    }
}

fn default_project_workspace_id(project_id: &str) -> String {
    format!("{project_id}-workspace-1")
}

fn default_project_window_id(project_id: &str) -> String {
    format!("{project_id}-window-1")
}

fn default_project_pane_session_id(project_id: &str) -> String {
    format!("{project_id}-pane-1")
}

/// Record window→project OWNERSHIP: append `window_id` to the project's `window_order` if absent. Idempotent + best-
/// effort. Without this a newly-created window is orphaned — the dashboard snapshot can't associate it to its project
/// (no window_order owner + no task/workspace link), so it lands in `unassigned_windows` and never reaches the remote
/// browser (the "2 local windows, only 1 in the browser" bug). Call after every new-window creation.
#[cfg(test)]
fn ensure_window_in_project_order(
    paths: &AppPaths,
    project_id: &str,
    window_id: &str,
    now_ms: u64,
) {
    match WindowLayoutService::new(paths).ensure_project_assignment(
        window_id, project_id, now_ms,
    ) {
        Ok(maestro_shell::ConditionalWindowProjectAssignment::Applied(_)) => {}
        Ok(outcome) => eprintln!(
            "attach-tab: atomic window ownership refused project={project_id:?} window={window_id:?} outcome={outcome:?}"
        ),
        Err(error) => eprintln!(
            "attach-tab: atomic window ownership failed project={project_id:?} window={window_id:?} (non-fatal): {error}"
        ),
    }
}

/// Keep a WINDOW name unique WITHIN its project (auto-number collisions). WindowLayoutService only has one window
/// record, so window-scope uniqueness lives here: gather the project's OTHER window names (via `window_order` →
/// load each layout's name), EXCLUDING `self_window_id` (so rename-to-self is a no-op), then `unique_name`. Best-effort:
/// a missing/unreadable project or an orphaned window (not in window_order) simply yields no siblings → no dedup.
fn unique_window_name(
    paths: &AppPaths,
    project_id: &str,
    self_window_id: &str,
    desired: &str,
) -> String {
    let windows = WindowLayoutService::new(paths);
    let sibling_names: Vec<String> =
        match maestro_shell::ProjectService::new(paths).load(project_id) {
            Ok(Some(project)) => project
                .window_order
                .iter()
                .filter(|wid| wid.as_str() != self_window_id)
                .filter_map(|wid| windows.load(wid).ok().flatten())
                .filter_map(|layout| layout.name.clone())
                .collect(),
            _ => Vec::new(),
        };
    maestro_shell::unique_name(desired, &sibling_names)
}

#[allow(clippy::too_many_arguments)]
#[cfg(test)]
fn seed_project_window_record(
    paths: &AppPaths,
    project_id: &str,
    root: &str,
    workspace_id: &str,
    window_id: &str,
    window_name: &str,
    session_id: &str,
    pane_id: &str,
    pane_name: &str,
    kind: SessionKind,
    launch: LaunchSpec,
    now_ms: u64,
) -> Result<(), String> {
    let workspace = Workspace {
        workspace_id: workspace_id.to_string(),
        project_id: project_id.to_string(),
        root: root.to_string(),
        policy: maestro_shell::WorkspacePolicy::ScratchCwd,
        consent: WorkspaceConsent::default(),
    };
    let session = SessionRecord {
        session_id: session_id.to_string(),
        workspace_id: workspace_id.to_string(),
        kind,
        launch,
        cwd_resolved: root.to_string(),
        agent_task_id: None,
        created_at_ms: now_ms,
        last_attached_at_ms: now_ms,
        last_known_generation: None,
        status: SessionStatus::Unknown,
    };
    let spec = maestro_shell::FreshWindowGraphSpec {
        workspace,
        session,
        window_id: window_id.to_string(),
        window_name: window_name.to_string(),
        tab_id: pane_id.to_string(),
        tab_title: pane_name.to_string(),
        tab_pinned: false,
        tab_attention: AttentionState::default(),
        touch_project: false,
    };
    let expected_project = WindowLayoutService::new(paths)
        .load_project_window_graph_snapshot(project_id)
        .map_err(|error| format!("load seed Project: {error}"))?
        .ok_or_else(|| format!("seed Project {project_id:?} is missing"))?;
    match WindowLayoutService::new(paths)
        .create_fresh_window_graph(&expected_project, spec, now_ms)
        .map_err(|error| format!("create complete initial window graph: {error}"))?
    {
        maestro_shell::FreshWindowGraphCreateOutcome::Created(_) => {}
        outcome => {
            return Err(format!(
                "fresh initial window graph refused project={project_id:?} window={window_id:?}: {outcome:?}"
            ));
        }
    }
    eprintln!(
        "seed: project={project_id:?} window={window_id:?} pane={pane_id:?} session={session_id:?} kind={kind:?} \
         → workspace+session+owned-window+tab committed atomically"
    );
    Ok(())
}

