    #[test]
    fn claimed_fresh_projection_reloads_cosmetic_bytes_but_rejects_deleted_target() {
        let (_tmp, paths, _existing, _template, layout) = fixture();
        let tab_id = "existing-pane";
        let claimed = load_renderer_viewport_projection(&paths, &layout.window_id, tab_id)
            .expect("load pre-Claim target");
        WindowLayoutService::new(&paths)
            .update_attention(
                &layout.window_id,
                tab_id,
                AttentionState {
                    attention: maestro_shell::Attention::Activity,
                    unseen: true,
                    since_ms: 9,
                    source: maestro_shell::AttentionSource::Process,
                },
                9,
            )
            .expect("cosmetic concurrent update");
        let current = load_current_claimed_fresh_projection(&paths, &claimed)
            .expect("same exact cohort reloads current cosmetic projection");
        assert_eq!(current.exact_viewport(), claimed.exact_viewport());
        assert_ne!(current.tab_strip(), claimed.tab_strip());

        WindowLayoutService::new(&paths)
            .delete(&layout.window_id)
            .expect("delete claimed target");
        assert!(load_current_claimed_fresh_projection(&paths, &claimed).is_err());
    }

    #[test]
    fn claimed_fresh_projection_rejects_tab_retarget_and_sibling_cohort_mutation() {
        {
            let (_tmp, paths, existing, _template, layout) = fixture();
            let claimed =
                load_renderer_viewport_projection(&paths, &layout.window_id, "existing-pane")
                    .expect("load pre-retarget projection");
            let mut replacement = existing.clone();
            replacement.session_id = "react-retarget-session".into();
            replacement.last_known_generation = Some("react-retarget-generation".into());
            write_record(
                &paths,
                RecordKind::Session,
                &replacement.session_id,
                10,
                &replacement,
            )
            .expect("write replacement Session");
            WindowLayoutService::new(&paths)
                .retarget_tab_session(
                    &layout.window_id,
                    "existing-pane",
                    &replacement.session_id,
                    10,
                )
                .expect("retarget claimed tab");
            assert!(load_current_claimed_fresh_projection(&paths, &claimed).is_err());
        }

        {
            let (_tmp, paths, existing, _template, layout) = fixture();
            let claimed =
                load_renderer_viewport_projection(&paths, &layout.window_id, "existing-pane")
                    .expect("load pre-split projection");
            let mut sibling = existing;
            sibling.session_id = "react-sibling-session".into();
            sibling.last_known_generation = Some("react-sibling-generation".into());
            write_record(
                &paths,
                RecordKind::Session,
                &sibling.session_id,
                11,
                &sibling,
            )
            .expect("write sibling Session");
            WindowLayoutService::new(&paths)
                .split_tab(
                    &layout.window_id,
                    "existing-pane",
                    "react-sibling-pane",
                    &sibling.session_id,
                    "Sibling",
                    maestro_shell::SplitAxis::Right,
                    11,
                )
                .expect("add concurrent sibling");
            assert!(load_current_claimed_fresh_projection(&paths, &claimed).is_err());
        }
    }

