    #[test]
    fn react_window_graph_exhaustion_preserves_collided_winner_and_project_order() {
        let (_tmp, paths, _existing, template, layout_before) = fixture();
        let project_before = maestro_shell::ProjectService::new(&paths)
            .load("react-insert-project")
            .unwrap()
            .unwrap();
        let expected_project = WindowLayoutService::new(&paths)
            .load_project_window_graph_snapshot("react-insert-project")
            .unwrap()
            .unwrap();
        let result = create_fresh_react_window_graph(
            &paths,
            &expected_project,
            "/fresh/requested",
            "Fresh",
            "Pane 1",
            &template,
            9,
            |_| {
                (
                    "react-insert-workspace".into(),
                    "react-never-window".into(),
                    "react-never-session".into(),
                )
            },
            |_| true,
        );
        assert!(matches!(
            result,
            Err(ReactWindowGraphCreateError::Exhausted)
        ));
        assert_eq!(
            maestro_shell::ProjectService::new(&paths)
                .load("react-insert-project")
                .unwrap(),
            Some(project_before)
        );
        assert!(
            load_one::<SessionRecord>(&paths, RecordKind::Session, "react-never-session")
                .unwrap()
                .is_none()
        );
        assert!(WindowLayoutService::new(&paths)
            .load("react-never-window")
            .unwrap()
            .is_none());
        assert_eq!(
            WindowLayoutService::new(&paths)
                .load("react-insert-window")
                .unwrap(),
            Some(layout_before)
        );
    }

