    #[test]
    fn authoritative_loss_stays_neutral_when_fallback_enumeration_is_unavailable() {
        let temp = tempfile::tempdir().expect("tempdir");
        let base = temp.path().join("base");
        let paths = AppPaths::with_base(&base);
        let (mut runtime, commands) = RendererTabRuntime::new();
        runtime.seed_active_tab("lost-window", "lost-tab", "lost-session");
        let strip_tabs = vec![WindowTabJson {
            tab_id: "lost-tab".to_string(),
            session_id: "lost-session".to_string(),
            index: 0,
            title: "Lost".to_string(),
            pinned: false,
            attention: AttentionJson {
                attention: "none".to_string(),
                unseen: false,
                since_ms: 0,
                source: "process".to_string(),
            },
            split_from: None,
            pane_rect: None,
        }];
        let selection = maestro_app::selection_from_strip_tabs(&strip_tabs);
        let initial_strip =
            maestro_app::build_tab_strip_model("lost-window", &strip_tabs, Some("lost-tab"))
                .expect("initial strip");
        inject_window_projection_fault(&paths, "deletion-fallback-window-read", "lost-window", 1);
        let (events_tx, events_rx) = mpsc::channel();
        let listener = spawn_window_event_listener(
            runtime,
            events_rx,
            maestro_app::update_check::spawn_update_check(),
            "lost-window".into(),
            selection,
            strip_tabs,
            paths,
            base,
            temp.path().join("absent-daemon.sock"),
            None,
            initial_strip,
            "test".into(),
            None,
            None,
            false,
            RecordedPaneOpenPolicy::Ordinary,
            ListenerWindowContext::PublishedForTest,
        );

        let deadline = Instant::now() + Duration::from_secs(3);
        let mut observed = Vec::new();
        loop {
            let command = commands
                .recv_timeout(deadline.saturating_duration_since(Instant::now()))
                .expect(
                    "authoritative missing layout clears before the injected fallback read fault",
                );
            let cleared = matches!(command, maestro_renderer::RendererCommand::ClearViewport);
            observed.push(command);
            if cleared {
                break;
            }
        }
        drop(events_tx);
        assert_eq!(
            listener.shutdown_and_join_with_timeout(Duration::from_secs(2)),
            WindowEventListenerShutdown::Completed
        );
        observed.extend(commands.try_iter());
        let ownership: Vec<_> = observed
            .into_iter()
            .filter(|command| {
                matches!(
                    command,
                    maestro_renderer::RendererCommand::ClearViewport
                        | maestro_renderer::RendererCommand::AttachSession { .. }
                        | maestro_renderer::RendererCommand::SetTabStrip { .. }
                )
            })
            .collect();
        assert_eq!(
            ownership,
            vec![maestro_renderer::RendererCommand::ClearViewport],
            "the real fallback ReadUnavailable branch remains neutral after its one clear"
        );
    }

    fn run_atomic_stash_window_final_read_fault() -> Vec<maestro_renderer::RendererCommand> {
        let temp = tempfile::tempdir().expect("tempdir");
        let base = temp.path().join("atomic-stash-final-read-fault");
        let paths = AppPaths::with_base(&base);
        let project_id = "atomic-stash-project";
        let window_id = "atomic-stash-window";
        let fallback_id = format!("{window_id}-fallback");
        ProjectService::new(&paths)
            .create(
                project_id,
                "Stash fault",
                temp.path().to_string_lossy(),
                NewProject::default(),
                1,
            )
            .expect("create project");
        let windows = WindowLayoutService::new(&paths);
        windows.create_empty(window_id, 2).expect("create target");
        windows
            .open_tab(
                window_id,
                "active-tab",
                "active-session",
                "Active",
                false,
                AttentionState::default(),
                3,
            )
            .expect("open active");
        let initial = windows
            .open_tab(
                window_id,
                "inactive-tab",
                "inactive-session",
                "Inactive",
                false,
                AttentionState::default(),
                4,
            )
            .expect("open inactive");
        windows
            .create_empty(&fallback_id, 5)
            .expect("create fallback");
        windows
            .open_tab(
                &fallback_id,
                "fallback-tab",
                "fallback-session",
                "Fallback",
                false,
                AttentionState::default(),
                6,
            )
            .expect("open fallback");
        for id in [window_id, fallback_id.as_str()] {
            store::set_window_project(&paths, id, project_id).expect("assign project window");
        }
        ProjectService::new(&paths)
            .reorder_windows(project_id, &[window_id.to_string(), fallback_id.clone()], 7)
            .expect("order windows");

        let strip_tabs = maestro_app::live_tab_records_json(&initial.tabs);
        let selection = maestro_app::selection_from_strip_tabs(&strip_tabs);
        let initial_strip =
            maestro_app::build_tab_strip_model(window_id, &strip_tabs, Some("active-tab"))
                .expect("initial strip");
        let (mut runtime, renderer_commands) = RendererTabRuntime::new();
        runtime.seed_active_tab(window_id, "active-tab", "active-session");
        inject_window_projection_fault(&paths, "stash-window-final-load", window_id, 1);
        let (events_tx, events_rx) = mpsc::channel();
        let listener = spawn_window_event_listener(
            runtime,
            events_rx,
            maestro_app::update_check::spawn_update_check(),
            window_id.to_string(),
            selection,
            strip_tabs,
            paths.clone(),
            base,
            temp.path().join("absent-daemon.sock"),
            None,
            initial_strip,
            "test".into(),
            None,
            None,
            false,
            RecordedPaneOpenPolicy::Ordinary,
            ListenerWindowContext::PublishedForTest,
        );
        events_tx
            .send(maestro_renderer::RendererEvent::ReactChromeIntent {
                json: format!(
                    r#"{{"type":"stashWindow","project_id":"{project_id}","window_id":"{window_id}"}}"#
                ),
            })
            .expect("dispatch production stashWindow intent");
        // FIFO acknowledgement: this harmless global intent is handled only after the stash branch
        // returns, and avoids waiting into the later 250ms authoritative retry tick (which is allowed
        // to reproject after a new successful read).
        events_tx
            .send(maestro_renderer::RendererEvent::ReactChromeIntent {
                json: r#"{"type":"focusTerminal"}"#.into(),
            })
            .expect("queue post-stash acknowledgement");

        let deadline = Instant::now() + Duration::from_secs(3);
        let mut commands = Vec::new();
        loop {
            let command = renderer_commands
                .recv_timeout(deadline.saturating_duration_since(Instant::now()))
                .expect("post-stash acknowledgement reaches renderer");
            let acknowledged = matches!(command, maestro_renderer::RendererCommand::FocusTerminal);
            commands.push(command);
            if acknowledged {
                break;
            }
        }
        let atomic_mutation_observed = WindowLayoutService::new(&paths)
            .load(window_id)
            .ok()
            .flatten()
            .is_some_and(|layout| {
                let active_stashed = layout
                    .tabs
                    .iter()
                    .find(|tab| tab.tab_id == "active-tab")
                    .is_some_and(|tab| tab.stashed);
                let inactive_stashed = layout
                    .tabs
                    .iter()
                    .find(|tab| tab.tab_id == "inactive-tab")
                    .is_some_and(|tab| tab.stashed);
                active_stashed && inactive_stashed
            });
        assert!(
            atomic_mutation_observed,
            "the whole window stash must commit atomically"
        );
        drop(events_tx);
        assert_eq!(
            listener.shutdown_and_join_with_timeout(Duration::from_secs(2)),
            WindowEventListenerShutdown::Completed
        );
        commands.extend(renderer_commands.try_iter());
        commands
            .into_iter()
            .filter(|command| {
                matches!(
                    command,
                    maestro_renderer::RendererCommand::ClearViewport
                        | maestro_renderer::RendererCommand::AttachSession { .. }
                        | maestro_renderer::RendererCommand::SetTabStrip { .. }
                )
            })
            .collect()
    }

    #[test]
    fn atomic_stash_window_final_read_error_clears_exactly_once() {
        assert_eq!(
            run_atomic_stash_window_final_read_fault(),
            vec![maestro_renderer::RendererCommand::ClearViewport]
        );
    }

    fn run_tab_close_final_read_fault(
        close_active: bool,
    ) -> Vec<maestro_renderer::RendererCommand> {
        let temp = tempfile::tempdir().expect("tempdir");
        let base = temp.path().join(if close_active {
            "close-active"
        } else {
            "close-inactive"
        });
        let paths = AppPaths::with_base(&base);
        let project_id = if close_active {
            "close-active-project"
        } else {
            "close-inactive-project"
        };
        let window_id = if close_active {
            "close-active-window"
        } else {
            "close-inactive-window"
        };
        ProjectService::new(&paths)
            .create(
                project_id,
                "Close fault",
                temp.path().to_string_lossy(),
                NewProject::default(),
                1,
            )
            .expect("create project");
        let windows = WindowLayoutService::new(&paths);
        windows.create_empty(window_id, 2).expect("create window");
        windows
            .open_tab(
                window_id,
                "active-tab",
                "active-session",
                "Active",
                false,
                AttentionState::default(),
                3,
            )
            .expect("open active");
        let initial = windows
            .open_tab(
                window_id,
                "inactive-tab",
                "inactive-session",
                "Inactive",
                false,
                AttentionState::default(),
                4,
            )
            .expect("open inactive");
        store::set_window_project(&paths, window_id, project_id).expect("assign window");
        ProjectService::new(&paths)
            .reorder_windows(project_id, &[window_id.to_string()], 5)
            .expect("order window");

        let strip_tabs = maestro_app::live_tab_records_json(&initial.tabs);
        let selection = maestro_app::selection_from_strip_tabs(&strip_tabs);
        let initial_strip =
            maestro_app::build_tab_strip_model(window_id, &strip_tabs, Some("active-tab"))
                .expect("initial strip");
        let (mut runtime, renderer_commands) = RendererTabRuntime::new();
        runtime.seed_active_tab(window_id, "active-tab", "active-session");
        inject_window_projection_fault(&paths, "tab-close-final-load", window_id, 1);
        let (events_tx, events_rx) = mpsc::channel();
        let listener = spawn_window_event_listener(
            runtime,
            events_rx,
            maestro_app::update_check::spawn_update_check(),
            window_id.to_string(),
            selection,
            strip_tabs,
            paths.clone(),
            base,
            temp.path().join("absent-daemon.sock"),
            None,
            initial_strip,
            "test".into(),
            None,
            None,
            false,
            RecordedPaneOpenPolicy::Ordinary,
            ListenerWindowContext::PublishedForTest,
        );
        let closing_tab = if close_active {
            "active-tab"
        } else {
            "inactive-tab"
        };
        events_tx
            .send(maestro_renderer::RendererEvent::TabCloseRequested {
                window_id: window_id.to_string(),
                tab_id: closing_tab.to_string(),
            })
            .expect("dispatch production close event");
        events_tx
            .send(maestro_renderer::RendererEvent::ReactChromeIntent {
                json: r#"{"type":"focusTerminal"}"#.into(),
            })
            .expect("queue post-close acknowledgement");

        let deadline = Instant::now() + Duration::from_secs(3);
        let mut commands = Vec::new();
        loop {
            let command = renderer_commands
                .recv_timeout(deadline.saturating_duration_since(Instant::now()))
                .expect("post-close acknowledgement reaches renderer");
            let acknowledged = matches!(command, maestro_renderer::RendererCommand::FocusTerminal);
            commands.push(command);
            if acknowledged {
                break;
            }
        }
        let mutation_observed = WindowLayoutService::new(&paths)
            .load(window_id)
            .ok()
            .flatten()
            .is_some_and(|layout| {
                !layout.tabs.iter().any(|tab| tab.tab_id == closing_tab)
                    && layout.tabs.iter().any(|tab| tab.tab_id != closing_tab)
            });
        assert!(mutation_observed, "the requested tab close committed");
        drop(events_tx);
        assert_eq!(
            listener.shutdown_and_join_with_timeout(Duration::from_secs(2)),
            WindowEventListenerShutdown::Completed
        );
        commands.extend(renderer_commands.try_iter());
        commands
            .into_iter()
            .filter(|command| {
                matches!(
                    command,
                    maestro_renderer::RendererCommand::ClearViewport
                        | maestro_renderer::RendererCommand::AttachSession { .. }
                        | maestro_renderer::RendererCommand::SetTabStrip { .. }
                )
            })
            .collect()
    }

