    /// `settings_panel_row_to_renderer` maps every app `SettingsPanelRow` field into the renderer row
    /// exactly: the stable `id`/`category`/`label` and `value` carry through, a report-only row keeps
    /// `setting_key: None`/`editable: false`, and an editable row keeps its exact key + `editable:
    /// true`. The full panel projection preserves order/length 1:1 with the lines.
    #[test]
    fn settings_panel_rows_project_into_renderer_rows_exactly() {
        let base = std::env::temp_dir();
        let app_panel = build_settings_panel_lines(&effective_settings(&base));
        let rendered = settings_panel_to_renderer(&app_panel);

        assert_eq!(
            rendered.lines, app_panel.lines,
            "lines carry through unchanged"
        );
        assert_eq!(
            rendered.source,
            maestro_renderer::DashboardPanelSource::Settings,
            "projected panel is a settings panel"
        );
        assert_eq!(
            rendered.settings_rows.len(),
            app_panel.rows.len(),
            "one renderer row per app row"
        );
        assert_eq!(
            rendered.settings_rows.len(),
            app_panel.lines.len(),
            "rows stay 1:1 with lines"
        );

        for (app_row, r_row) in app_panel.rows.iter().zip(rendered.settings_rows.iter()) {
            assert_eq!(r_row.id, app_row.id, "id carries through");
            assert_eq!(r_row.category, app_row.category, "category carries through");
            assert_eq!(r_row.label, app_row.label, "label carries through");
            assert_eq!(r_row.value, app_row.value, "value carries through");
            assert_eq!(
                r_row.setting_key.as_deref(),
                app_row.setting_key,
                "setting_key carries through (including None)"
            );
            assert_eq!(r_row.editable, app_row.editable, "editable carries through");
        }

        // At least one report-only row (setting_key: None) and one editable row exist, so the
        // both-arms mapping is actually exercised.
        assert!(
            rendered
                .settings_rows
                .iter()
                .any(|r| r.setting_key.is_none() && !r.editable),
            "a report-only row maps to None/false"
        );
        assert!(
            rendered
                .settings_rows
                .iter()
                .any(|r| r.setting_key.is_some() && r.editable),
            "an editable row maps to Some(key)/true"
        );
    }

    /// The foreground `SettingsPanelCloseRequested` shortcut handler (the renderer-event arm) sends
