    /// The foreground `SettingsPanelRowSelected` arm is OBSERVE-ONLY: the renderer reports which
    /// settings row became selected, and the listener decodes the variant and does nothing that
    /// touches the renderer command channel, the tab record, settings, config, or the daemon. This
    /// reproduces the listener arm without a renderer and asserts NO tab runtime command is produced.
    #[test]
    fn settings_panel_row_selected_event_is_observe_only_no_command() {
        let (tab_runtime, tab_commands) = RendererTabRuntime::new();
        let (events_tx, events_rx) = std::sync::mpsc::channel::<maestro_renderer::RendererEvent>();

        events_tx
            .send(maestro_renderer::RendererEvent::SettingsPanelRowSelected {
                row_index: 1,
                row_id: "appearance.theme".to_string(),
                setting_key: Some("appearance.theme".to_string()),
                editable: true,
            })
            .expect("send selection intent on event channel");

        // Listener arm verbatim: decode and observe only — no command is sent.
        match events_rx.recv().expect("selection event round-trips") {
            maestro_renderer::RendererEvent::SettingsPanelRowSelected {
                row_index,
                row_id,
                setting_key,
                editable,
            } => {
                assert_eq!(row_index, 1);
                assert_eq!(row_id, "appearance.theme");
                assert_eq!(setting_key.as_deref(), Some("appearance.theme"));
                assert!(editable);
                // The handler logs only; it issues no renderer command.
            }
            other => panic!("unexpected event for selection round-trip: {other:?}"),
        }

        // The runtime is still live (never consulted by the arm) and NO command was queued.
        drop(tab_runtime);
        assert!(
            tab_commands.try_recv().is_err(),
            "the selection-intent arm sends no renderer command (read-only observation only)"
        );
    }

    /// The activation-policy helper, EDITABLE case: `editable` AND a `setting_key` is present. The
    /// label keeps the base identity prefix, includes the stable setting key, and says editing is not
    /// yet available — it must NOT claim a setting changed.
    #[test]
    fn settings_panel_activation_status_label_editable_includes_key_and_says_pending() {
        let label = settings_panel_activation_status_label(
            "session • shell",
            "appearance.theme",
            Some("appearance.theme"),
            true,
        );
        assert!(
            label.starts_with("session • shell · "),
            "base prefix kept: {label}"
        );
        assert!(
            label.contains("appearance.theme"),
            "stable key included: {label}"
        );
        assert!(
            label.contains("editing not yet available"),
            "editable feedback is pending, not a mutation: {label}"
        );
        assert!(!label.contains('\n'), "single line: {label}");
    }

    /// The activation-policy helper, READ-ONLY cases: a non-editable row, or an editable flag with no
    /// setting key, both classify as read-only. The label says read-only and needs no key.
    #[test]
    fn settings_panel_activation_status_label_read_only_says_read_only() {
        let non_editable = settings_panel_activation_status_label(
            "session • shell",
            "appearance.header",
            None,
            false,
        );
        assert!(
            non_editable.contains("read-only"),
            "non-editable is read-only: {non_editable}"
        );
        assert!(!non_editable.contains('\n'), "single line: {non_editable}");

        // editable flag but NO setting key still classifies read-only (cannot edit an unkeyed row).
        let editable_no_key =
            settings_panel_activation_status_label("base", "row.without.key", None, true);
        assert!(
            editable_no_key.contains("read-only"),
            "editable-but-keyless classifies read-only: {editable_no_key}"
        );
    }

    /// The helper is bounded and sanitized: control characters in the row id / key are stripped (so
    /// the status row cannot be injected with newlines/escapes) and over-long fragments are capped.
    #[test]
    fn settings_panel_activation_status_label_is_bounded_and_sanitized() {
        let nasty_id = format!("evil\n\u{1b}[31mid{}", "x".repeat(200));
        let nasty_key = format!("k\ney{}", "y".repeat(200));
        let label =
            settings_panel_activation_status_label("base", &nasty_id, Some(&nasty_key), true);
        assert!(
            !label.contains('\n'),
            "no embedded newline survives: {label:?}"
        );
        assert!(
            !label.contains('\u{1b}'),
            "no embedded escape survives: {label:?}"
        );
        // Each fragment is capped at SETTINGS_ACTIVATION_ID_CAP chars, so the whole label stays
        // comfortably bounded regardless of the oversized inputs.
        assert!(
            label.len() < 256,
            "label stays bounded: len={}",
            label.len()
        );
    }

    /// Reproduce the foreground `SettingsPanelRowActivated` listener arm without a renderer: decode the
    /// event, classify editable-keyed vs read-only exactly as the arm does, and drive the same
    /// `tab_runtime` sends. Returns the row id/key/editable so each test can assert the commands.
    fn run_activation_arm(
        tab_runtime: &mut RendererTabRuntime,
        base: &str,
        event: maestro_renderer::RendererEvent,
    ) {
        match event {
            maestro_renderer::RendererEvent::SettingsPanelRowActivated {
                row_id,
                setting_key,
                editable,
                ..
            } => match setting_key.filter(|_| editable) {
                Some(key) => {
                    let draft = maestro_renderer::RendererSettingsPanelEditDraft {
                        row_id: row_id.clone(),
                        setting_key: key,
                        value: String::new(),
                        validation: None,
                    };
                    tab_runtime
                        .set_settings_edit_draft(Some(draft))
                        .expect("edit-draft send succeeds with a live channel");
                }
                None => {
                    let activation_label =
                        settings_panel_activation_status_label(base, &row_id, None, false);
                    tab_runtime
                        .set_status_label(Some(activation_label))
                        .expect("status-label send succeeds with a live channel");
                    tab_runtime
                        .set_settings_edit_draft(None)
                        .expect("draft-clear send succeeds with a live channel");
                }
            },
            other => panic!("unexpected event for activation round-trip: {other:?}"),
        }
    }

    /// An EDITABLE keyed activation sends EXACTLY ONE display-only `SetSettingsPanelEditDraft(Some(..))`
    /// carrying the stable row id + setting key, and NO mutating/session/tab/window/status command.
    #[test]
    fn settings_panel_editable_activation_sends_one_edit_draft_and_nothing_else() {
        let (mut tab_runtime, tab_commands) = RendererTabRuntime::new();
        let base = "session • shell".to_string();

        run_activation_arm(
            &mut tab_runtime,
            &base,
            maestro_renderer::RendererEvent::SettingsPanelRowActivated {
                row_index: 1,
                row_id: "appearance.theme".to_string(),
                setting_key: Some("appearance.theme".to_string()),
                editable: true,
            },
        );

        match tab_commands.try_recv() {
            Ok(maestro_renderer::RendererCommand::SetSettingsPanelEditDraft { draft }) => {
                let draft = draft.expect("editable activation opens a draft");
                assert_eq!(draft.row_id, "appearance.theme");
                assert_eq!(draft.setting_key, "appearance.theme");
                assert_eq!(
                    draft.value, "",
                    "an app-created draft starts with an empty local value"
                );
                assert!(
                    draft.validation.is_none(),
                    "an app-created draft starts with no validation verdict (validation is renderer-local)"
                );
            }
            other => panic!("expected one SetSettingsPanelEditDraft(Some), got {other:?}"),
        }
        assert!(
            tab_commands.try_recv().is_err(),
            "an editable activation sends exactly one command and nothing else"
        );
    }

    /// Reproduce the foreground `SettingsPanelEditDraftSubmitted` listener arm without a renderer: it
    /// re-validates app-side via [`plan_settings_panel_submit`], persists the writable key through the
    /// existing atomic `set_chrome_default` path, and on success refreshes the panel
    /// (`build_settings_panel_lines(&effective_settings(base_path))` -> `settings_panel_to_renderer`),
    /// clears the draft, and sends a bounded saved status. On any
    /// invalid-value/unsupported-key/write-failure it writes nothing, keeps the draft, and sends a
    /// bounded not-saved status. Mirrors the real arm 1:1 so the tests exercise the actual policy.
    fn run_submit_arm(
        tab_runtime: &mut RendererTabRuntime,
        base_path: &std::path::Path,
        base_label: &str,
        setting_key: &str,
        value: &str,
    ) {
        let write_outcome = match plan_settings_panel_submit(setting_key, value) {
            SettingsPanelSubmitPlan::WriteChromeBool(chrome_key, parsed) => {
                Some(set_chrome_default(base_path, chrome_key, parsed))
            }
            SettingsPanelSubmitPlan::WriteTheme(theme) => Some(set_theme(base_path, &theme)),
            SettingsPanelSubmitPlan::WriteFontSize(px) => Some(set_font_size_px(base_path, px)),
            SettingsPanelSubmitPlan::WriteShellArgv(argv) => {
                Some(set_shell_default_argv(base_path, &argv))
            }
            SettingsPanelSubmitPlan::WriteWorkspacePolicy(policy) => {
                Some(set_workspace_default_policy(base_path, &policy))
            }
            SettingsPanelSubmitPlan::WriteWorkspaceConsent(key, parsed) => {
                Some(set_workspace_consent(base_path, key, parsed))
            }
            SettingsPanelSubmitPlan::InvalidValue => {
                let label = settings_panel_submit_status_label(
                    base_label,
                    setting_key,
                    SettingsPanelSubmitOutcome::InvalidValue,
                );
                tab_runtime
                    .set_status_label(Some(label))
                    .expect("invalid-value-status send succeeds with a live channel");
                None
            }
            SettingsPanelSubmitPlan::UnsupportedKey => {
                let label = settings_panel_submit_status_label(
                    base_label,
                    setting_key,
                    SettingsPanelSubmitOutcome::UnsupportedKey,
                );
                tab_runtime
                    .set_status_label(Some(label))
                    .expect("unsupported-key-status send succeeds with a live channel");
                None
            }
        };
        match write_outcome {
            Some(Ok(_)) => {
                let panel_lines = build_settings_panel_lines(&effective_settings(base_path));
                let panel = settings_panel_to_renderer(&panel_lines);
                tab_runtime
                    .set_dashboard_panel(Some(panel))
                    .expect("refreshed panel send succeeds with a live channel");
                tab_runtime
                    .set_settings_edit_draft(None)
                    .expect("draft-clear send succeeds with a live channel");
                let label = settings_panel_submit_status_label(
                    base_label,
                    setting_key,
                    SettingsPanelSubmitOutcome::Saved,
                );
                tab_runtime
                    .set_status_label(Some(label))
                    .expect("saved-status send succeeds with a live channel");
            }
            Some(Err(failure)) => {
                let label = settings_panel_submit_status_label(
                    base_label,
                    setting_key,
                    SettingsPanelSubmitOutcome::WriteFailed(&failure.error_kind),
                );
                tab_runtime
                    .set_status_label(Some(label))
                    .expect("write-failed-status send succeeds with a live channel");
            }
            None => {}
        }
    }

    #[test]
    fn plan_settings_panel_submit_accepts_every_chrome_boolean() {
        // Each chrome boolean key parses true/false case-insensitively (whitespace tolerated) and maps
        // to its ChromeDefaultKey; a bad value for a writable key is InvalidValue; any non-chrome key
        // is UnsupportedKey regardless of its value.
        for (key, chrome_key) in [
            ("chrome.top_tab_bar_default", ChromeDefaultKey::TopTabBar),
            (
                "chrome.dashboard_status_default",
                ChromeDefaultKey::DashboardStatus,
            ),
            (
                "chrome.dashboard_panel_default",
                ChromeDefaultKey::DashboardPanel,
            ),
            (
                "chrome.picker_overlay_default",
                ChromeDefaultKey::PickerOverlay,
            ),
        ] {
            assert_eq!(
                plan_settings_panel_submit(key, "true"),
                SettingsPanelSubmitPlan::WriteChromeBool(chrome_key, true),
                "{key} writes true"
            );
            assert_eq!(
                plan_settings_panel_submit(key, "  FALSE  "),
                SettingsPanelSubmitPlan::WriteChromeBool(chrome_key, false),
                "{key} writes false (case/whitespace tolerated)"
            );
            for bad in ["1", "0", "yes", "no", "tru", ""] {
                assert_eq!(
                    plan_settings_panel_submit(key, bad),
                    SettingsPanelSubmitPlan::InvalidValue,
                    "bad value {bad:?} for writable key {key} does not write"
                );
            }
        }
        assert_eq!(
            plan_settings_panel_submit("some.unknown.key", "true"),
            SettingsPanelSubmitPlan::UnsupportedKey,
            "unknown key is not writable"
        );
    }

    #[test]
    fn plan_settings_panel_submit_accepts_shell_argv() {
        // shell.default_argv re-validates as a JSON array of strings with a non-empty first command
        // (whitespace around the whole value tolerated) and maps to WriteShellArgv carrying the parsed
        // argv. Malformed/non-array/non-string/empty-command values are InvalidValue (never a write,
        // never UnsupportedKey).
        assert_eq!(
            plan_settings_panel_submit("shell.default_argv", r#"["/bin/zsh","-l"]"#),
            SettingsPanelSubmitPlan::WriteShellArgv(vec!["/bin/zsh".to_string(), "-l".to_string()]),
            "valid JSON string array maps to WriteShellArgv"
        );
        assert_eq!(
            plan_settings_panel_submit("shell.default_argv", r#"  ["bash"]  "#),
            SettingsPanelSubmitPlan::WriteShellArgv(vec!["bash".to_string()]),
            "surrounding whitespace tolerated"
        );
        assert_eq!(
            plan_settings_panel_submit("shell.default_argv", r#"["sh",""]"#),
            SettingsPanelSubmitPlan::WriteShellArgv(vec!["sh".to_string(), String::new()]),
            "empty later args are allowed"
        );
        for bad in [
            "not json",
            r#"{"cmd":"zsh"}"#,
            "[]",
            "[1,2]",
            r#"[""]"#,
            r#"["  ","-l"]"#,
            r#""bash""#,
        ] {
            assert_eq!(
                plan_settings_panel_submit("shell.default_argv", bad),
                SettingsPanelSubmitPlan::InvalidValue,
                "bad shell argv {bad:?} does not write"
            );
        }
    }

    #[test]
    fn plan_settings_panel_submit_accepts_appearance_keys() {
        // appearance.theme re-validates against the supported themes (whitespace tolerated) and maps to
        // WriteTheme; appearance.font_size_px parses to an in-range u32 and maps to WriteFontSize. Bad
        // values for either are InvalidValue (never a write, never UnsupportedKey).
        assert_eq!(
            plan_settings_panel_submit("appearance.theme", "  built_in_dark  "),
            SettingsPanelSubmitPlan::WriteTheme("built_in_dark".to_string()),
            "valid theme maps to WriteTheme (trimmed)"
        );
        assert_eq!(
            plan_settings_panel_submit("appearance.theme", "high_contrast_dark"),
            SettingsPanelSubmitPlan::WriteTheme("high_contrast_dark".to_string()),
        );
        for bad in ["solarized", "BUILT_IN_DARK", ""] {
            assert_eq!(
                plan_settings_panel_submit("appearance.theme", bad),
                SettingsPanelSubmitPlan::InvalidValue,
                "unsupported theme {bad:?} does not write"
            );
        }
        assert_eq!(
            plan_settings_panel_submit("appearance.font_size_px", " 16 "),
            SettingsPanelSubmitPlan::WriteFontSize(16),
            "in-range integer maps to WriteFontSize (whitespace tolerated)"
        );
        for bad in ["9", "33", "big", "", "16.0", "-1"] {
            assert_eq!(
                plan_settings_panel_submit("appearance.font_size_px", bad),
                SettingsPanelSubmitPlan::InvalidValue,
                "bad font size {bad:?} does not write"
            );
        }
    }

    #[test]
    fn submit_arm_writes_top_tab_bar_and_refreshes_panel_then_clears_draft() {
        // The success path: persist via set_chrome_default, refresh the panel from
        // effective_settings(base) so the refreshed panel carries the NEW value, clear the draft, and
        // send a bounded saved status — in that order, and nothing else.
        let tmp = tempfile::tempdir().expect("tempdir");
        let base = tmp.path();
        // Seed a known starting value so the refreshed panel visibly flips.
        set_chrome_default(base, ChromeDefaultKey::TopTabBar, false).expect("seed false");
        assert!(
            !effective_settings(base).chrome.top_tab_bar_default,
            "precondition: top_tab_bar_default starts false"
        );

        let (mut tab_runtime, tab_commands) = RendererTabRuntime::new();
        run_submit_arm(
            &mut tab_runtime,
            base,
            "session • shell",
            "chrome.top_tab_bar_default",
            "true",
        );

        // The write actually persisted.
        assert!(
            effective_settings(base).chrome.top_tab_bar_default,
            "the submit wrote chrome.top_tab_bar_default=true through the existing settings path"
        );

        // First, the refreshed panel carries the new value (matching the new-state projection).
        match tab_commands.try_recv() {
            Ok(maestro_renderer::RendererCommand::SetDashboardPanel { dashboard_panel }) => {
                let panel = dashboard_panel.expect("refreshed panel is present");
                let expected = settings_panel_to_renderer(&build_settings_panel_lines(
                    &effective_settings(base),
                ));
                assert_eq!(
                    panel.lines, expected.lines,
                    "refreshed panel comes from build_settings_panel_lines(&effective_settings(base))"
                );
                assert!(
                    panel.lines.iter().any(|l| l.contains("true")),
                    "refreshed panel visibly carries the new top-tab-bar default: {:?}",
                    panel.lines
                );
            }
            other => panic!("expected refreshed SetDashboardPanel first, got {other:?}"),
        }
        // Second, the draft is cleared.
        match tab_commands.try_recv() {
            Ok(maestro_renderer::RendererCommand::SetSettingsPanelEditDraft { draft }) => {
                assert!(draft.is_none(), "a successful write clears the draft");
            }
            other => panic!("expected SetSettingsPanelEditDraft(None) second, got {other:?}"),
        }
        // Third, a bounded saved status is shown.
        match tab_commands.try_recv() {
            Ok(maestro_renderer::RendererCommand::SetStatusLabel { status_label }) => {
                let label = status_label.expect("saved status is present");
                assert!(
                    label.contains("chrome.top_tab_bar_default") && label.contains("saved"),
                    "bounded saved feedback: {label:?}"
                );
            }
            other => panic!("expected SetStatusLabel(Some) third, got {other:?}"),
        }
        assert!(
            tab_commands.try_recv().is_err(),
            "a successful submit sends exactly panel, draft-clear, saved-status and nothing else"
        );
    }

