    /// Handling `CommandPaletteOpenRequested` rebuilds the full catalog + preview, projects it through
    /// `command_palette_to_renderer_model`, and sends EXACTLY ONE display-only
    /// `SetCommandPaletteOverlay { Some(model) }` — empty initial query, no result line — and NOTHING
    /// else: no execution/result/dismiss command. Reproduces the listener composition without launching
    /// a renderer.
    #[test]
    fn command_palette_open_request_sends_one_overlay_model_and_nothing_else() {
        use super::{
            build_command_palette, command_palette_to_renderer_model, with_command_palette_preview,
        };
        let (mut tab_runtime, tab_commands) = RendererTabRuntime::new();

        // The same rebuild the foreground listener runs for the open intent.
        let base = std::env::temp_dir().to_string_lossy().into_owned();
        let full = with_command_palette_preview(build_command_palette(base));
        let model = command_palette_to_renderer_model(&full, None);
        tab_runtime
            .set_command_palette_overlay(Some(model))
            .expect("overlay command sends on open channel");

        match tab_commands.try_recv() {
            Ok(maestro_renderer::RendererCommand::SetCommandPaletteOverlay { command_palette }) => {
                let model = command_palette.expect("open sends a present model");
                assert!(
                    !model.rows.is_empty(),
                    "the rebuilt catalog carries the full action list"
                );
                assert!(
                    model.query.is_none(),
                    "open seeds an empty initial query (no filter)"
                );
            }
            other => panic!("expected one SetCommandPaletteOverlay(Some), got {other:?}"),
        }
        assert!(
            tab_commands.try_recv().is_err(),
            "open sends exactly one overlay command and NO result/dismiss/execution command"
        );
    }

    /// The no-policy `+` decline path the foreground listener runs must produce a SINGLE visible
    /// status-label command and NO session/strip/attach mutation command. This reproduces the exact
    /// listener composition: project a no-I/O snapshot, `plan_new_tab(None)` -> Decline, then send the
    /// composed decline label through the runtime. We assert one `SetStatusLabel(Some(..))` carrying
    /// the decline hint and nothing else on the wire.
    #[test]
    fn foreground_new_tab_no_policy_decline_sends_only_visible_status_command() {
        let (mut tab_runtime, rx) = maestro_app::RendererTabRuntime::new();
        tab_runtime.seed_active_tab("w1", "t0", "sess-t0");

        let strip_tabs: Vec<maestro_app::WindowTabJson> = Vec::new();
        let snapshot =
            maestro_app::new_tab_snapshot_from_strip_tabs(&strip_tabs, tab_runtime.active_tab_id());
        // No policy -> Decline, before any id minting (the production UUID gen never mints here).
        assert_eq!(
            maestro_app::plan_new_tab(None, &snapshot, &mut maestro_app::UuidIdGen),
            maestro_app::NewTabPlan::Decline,
            "no-policy new-tab must decline before id minting"
        );

        // The listener's visible-feedback send, verbatim.
        let base = "Maestro \u{b7} w1/t1 \u{b7} s-live";
        let decline_label = maestro_app::new_tab_decline_status_label(base);
        tab_runtime
            .set_status_label(Some(decline_label.clone()))
            .expect("status update sends on open channel");

        match rx.try_recv() {
            Ok(maestro_renderer::RendererCommand::SetStatusLabel { status_label }) => {
                assert_eq!(status_label.as_deref(), Some(decline_label.as_str()));
                assert!(
                    decline_label.ends_with(maestro_app::NEW_TAB_DECLINE_HINT),
                    "decline label must carry the launch-policy hint"
                );
            }
            other => panic!("expected one SetStatusLabel(Some), got {other:?}"),
        }
        assert!(
            rx.try_recv().is_err(),
            "decline sends exactly one command — no AttachSession/SetTabStrip mutation"
        );
        // The decline never invents active ownership from the textual compatibility seed.
        assert_eq!(tab_runtime.active_tab_id(), None);
    }

    // --- inactive-tab close against a REAL persisted layout (no GUI, temp app-support only) ---
    //
    // These exercise the exact composition the foreground listener performs: atomically remove and
    // capture one current tab via `WindowLayoutService::close_tab_with_removed`, reproject its
    // returned layout with `super::tab_json`, then refresh the strip. No daemon/PTY/GUI is used.

    use maestro_shell::paths::AppPaths;
    use maestro_shell::records::{AttentionSource, AttentionState};
    use maestro_shell::window_layout::WindowLayoutService;

    fn none_attention() -> AttentionState {
        AttentionState {
            attention: maestro_shell::records::Attention::None,
            unseen: false,
            since_ms: 0,
            source: AttentionSource::Process,
        }
    }

    /// A temp-backed two-tab window `w1` with tabs `t0` (active) and `t1` (inactive).
    fn two_tab_window(paths: &AppPaths) {
        let service = WindowLayoutService::new(paths);
        service.create_empty("w1", 0).expect("create window");
        service
            .open_tab("w1", "t0", "sess-t0", "shell", false, none_attention(), 0)
            .expect("open t0");
        service
            .open_tab("w1", "t1", "sess-t1", "logs", false, none_attention(), 0)
            .expect("open t1");
    }

    #[test]
    fn raw_inactive_close_helper_mutates_record_but_refuses_unproven_strip_refresh() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let paths = AppPaths::with_base(tmp.path());
        two_tab_window(&paths);

        // Active is t0; the listener closes the inactive t1 exactly as main.rs does.
        let (mut rt, rx) = maestro_app::RendererTabRuntime::new();
        rt.seed_active_tab("w1", "t0", "sess-t0");

        let closed = WindowLayoutService::new(&paths)
            .close_tab_with_removed("w1", "t1", 1)
            .expect("inactive close mutates the record");
        assert_eq!(closed.removed_tab.session_id, "sess-t1");
        let updated = closed.layout;
        assert!(
            updated.tabs.iter().all(|t| t.tab_id != "t1"),
            "the closed tab is gone from the persisted layout"
        );
        let new_strip_tabs: Vec<maestro_app::WindowTabJson> =
            updated.tabs.iter().map(super::tab_json).collect();

        assert!(matches!(
            rt.on_tab_close_requested("w1", &new_strip_tabs, "t0", "t1"),
            Err(maestro_app::TabSwitchError::ViewportAuthorityRequired)
        ));
        assert!(
            rx.try_recv().is_err(),
            "an unproven textual active coordinate cannot authorize SetTabStrip"
        );
        assert_eq!(rt.active_tab_id(), None);

        // The record really changed on disk: reloading shows only t0.
        let reloaded = WindowLayoutService::new(&paths)
            .load("w1")
            .expect("load")
            .expect("window exists");
        let ids: Vec<&str> = reloaded.tabs.iter().map(|t| t.tab_id.as_str()).collect();
        assert_eq!(ids, vec!["t0"]);
    }

    #[test]
    fn divider_ratio_persists_to_record_and_reattach_projection_restores_it() {
        use maestro_shell::SplitAxis;

        let tmp = tempfile::tempdir().expect("tempdir");
        let paths = AppPaths::with_base(tmp.path());
        let service = WindowLayoutService::new(&paths);
        service.create_empty("w1", 0).expect("create window");
        service
            .open_tab("w1", "t0", "sess-t0", "shell", false, none_attention(), 0)
            .expect("open t0");
        // Split a child `c1` off `t0`; it starts with no recorded ratio (even split).
        service
            .split_tab("w1", "t0", "c1", "sess-c1", "shell", SplitAxis::Right, 1)
            .expect("split c1 off t0");

        // The listener's `DividerRatioPersisted` arm body: persist the settled per-mille ratio for the
        // dragged child only, through the same single-field record path.
        service
            .set_split_ratio("w1", "c1", 640, 2)
            .expect("persist dragged child ratio");

        // The source tab keeps no split provenance, so the persist is scoped to the dragged child.
        let after = service.load("w1").expect("load").expect("window exists");
        let c1 = after.tabs.iter().find(|t| t.tab_id == "c1").unwrap();
        assert_eq!(
            c1.split_from.as_ref().and_then(|s| s.ratio_per_mille),
            Some(640)
        );
        assert!(after
            .tabs
            .iter()
            .find(|t| t.tab_id == "t0")
            .unwrap()
            .split_from
            .is_none());

        // Reattach/relaunch projection: reload from disk, project exactly as the listener does, and
        // confirm the renderer strip carries the restored per-mille ratio on the split child.
        let reloaded = WindowLayoutService::new(&paths)
            .load("w1")
            .expect("load")
            .expect("window exists");
        let strip_tabs: Vec<maestro_app::WindowTabJson> =
            reloaded.tabs.iter().map(super::tab_json).collect();
        let model = maestro_app::build_tab_strip_model("w1", &strip_tabs, Some("t0")).unwrap();
        let strip = maestro_app::renderer_tab_strip(&model);
        let projected = strip.tabs.iter().find(|t| t.tab_id == "c1").unwrap();
        assert_eq!(projected.split_ratio_per_mille, Some(640));
    }

    fn activity_attention() -> AttentionState {
        AttentionState {
            attention: maestro_shell::records::Attention::Activity,
            unseen: true,
            since_ms: 0,
            source: AttentionSource::Process,
        }
    }

    // The exact listener arm body for `TabAttentionClearRequested`: resolve the live active tab from
    // the runtime, then call the app-owned clear-and-refresh helper. Returns the helper result so the
    // test can assert one refreshed strip was sent and the record was cleared. Mirrors main.rs:
    // `current_active_tab_id` is the runtime's active tab; errors are surfaced (the production arm
    // logs them non-fatally instead).
    fn dispatch_attention_clear(
        paths: &AppPaths,
        rt: &mut maestro_app::RendererTabRuntime,
        window_id: &str,
        tab_id: &str,
    ) -> Result<maestro_app::TabAttentionClearRefresh, maestro_app::TabAttentionClearRefreshError>
    {
        let current_active_tab_id: Option<String> = rt.active_tab_id().map(str::to_owned);
        maestro_app::clear_tab_attention_and_refresh_strip(
            paths,
            rt,
            window_id,
            tab_id,
            current_active_tab_id.as_deref(),
            99,
        )
    }

    #[test]
    fn attention_clear_persists_but_unproven_viewport_refuses_strip_refresh() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let paths = AppPaths::with_base(tmp.path());
        // Two tabs; the active t0 carries persisted attention the click will clear.
        let service = WindowLayoutService::new(&paths);
        service.create_empty("w1", 0).expect("create window");
        service
            .open_tab(
                "w1",
                "t0",
                "sess-t0",
                "shell",
                false,
                activity_attention(),
                0,
            )
            .expect("open t0 with attention");
        service
            .open_tab("w1", "t1", "sess-t1", "logs", false, none_attention(), 0)
            .expect("open t1");

        let (events_tx, events_rx) = std::sync::mpsc::channel::<maestro_renderer::RendererEvent>();
        let (mut rt, rx) = maestro_app::RendererTabRuntime::new();
        rt.seed_active_tab("w1", "t0", "sess-t0");

        // The renderer emits an attention-clear intent for t0; the listener decodes it.
        events_tx
            .send(
                maestro_renderer::RendererEvent::TabAttentionClearRequested {
                    window_id: "w1".to_string(),
                    tab_id: "t0".to_string(),
                },
            )
            .expect("send attention-clear intent on open channel");
        let tab_id = match events_rx.recv().expect("event round-trips") {
            maestro_renderer::RendererEvent::TabAttentionClearRequested { tab_id, .. } => tab_id,
            other => panic!("expected attention-clear event, got {other:?}"),
        };

        let error = dispatch_attention_clear(&paths, &mut rt, "w1", &tab_id)
            .expect_err("an unproven viewport cannot receive a display-only strip refresh");
        assert!(matches!(
            error,
            maestro_app::TabAttentionClearRefreshError::ViewportAuthorityRequired
        ));
        assert!(rx.try_recv().is_err(), "no unproven strip command is sent");

        // The persisted attention on disk is cleared to none/seen/user.
        let reloaded = WindowLayoutService::new(&paths)
            .load("w1")
            .expect("load")
            .expect("window exists");
        let t0 = reloaded
            .tabs
            .iter()
            .find(|t| t.tab_id == "t0")
            .expect("t0 persisted");
        assert_eq!(
            t0.attention.attention,
            maestro_shell::records::Attention::None
        );
        assert!(!t0.attention.unseen);
        assert_eq!(t0.attention.source, AttentionSource::User);
    }

    #[test]
    fn listener_attention_clear_dispatch_error_is_nonfatal() {
        // A missing window makes the helper fail BEFORE any renderer command; the production arm logs
        // and keeps running, so here we only assert the error path is reached and nothing is sent.
        let tmp = tempfile::tempdir().expect("tempdir");
        let paths = AppPaths::with_base(tmp.path());
        let (mut rt, rx) = maestro_app::RendererTabRuntime::new();

        let err = dispatch_attention_clear(&paths, &mut rt, "ghost-w", "ghost-t")
            .expect_err("missing window must fail the clear");
        assert!(matches!(
            err,
            maestro_app::TabAttentionClearRefreshError::WindowLayout(_)
        ));
        assert!(rx.try_recv().is_err(), "no renderer command on failure");
    }

