    fn loaded<T: serde::de::DeserializeOwned>(paths: &AppPaths, kind: RecordKind, id: &str) -> T {
        match store::load_one(paths, kind, id).unwrap() {
            Some(LoadOutcome::Loaded(record)) => record,
            _ => panic!("expected loaded {kind:?} record {id:?}"),
        }
    }

    #[test]
    fn visible_project_reorder_preserves_hidden_recovery_and_rejects_partial_orders() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let paths = AppPaths::with_base(tmp.path().join("base"));
        let projects = ProjectService::new(&paths);
        projects
            .create(
                "project-a",
                "A",
                tmp.path().to_string_lossy(),
                NewProject::default(),
                30,
            )
            .unwrap();
        projects
            .create(
                "project-b",
                "B",
                tmp.path().to_string_lossy(),
                NewProject::default(),
                10,
            )
            .unwrap();
        let recovery =
            new_hidden_product_recovery_project(tmp.path().to_string_lossy().as_ref(), 20);
        store::write_record(
            &paths,
            RecordKind::Project,
            PRODUCT_RECOVERY_PROJECT_ID,
            20,
            &recovery,
        )
        .unwrap();

        let current = projects.list().unwrap();
        let visible = vec!["project-b".to_string(), "project-a".to_string()];
        let complete = complete_visible_project_order(&current, &visible).unwrap();
        assert_eq!(
            complete,
            vec![
                "project-b".to_string(),
                PRODUCT_RECOVERY_PROJECT_ID.to_string(),
                "project-a".to_string(),
            ],
            "the internal row keeps its slot while visible rows realize the requested order"
        );
        projects.reorder(&complete, 40).unwrap();
        assert_eq!(
            projects
                .list()
                .unwrap()
                .into_iter()
                .map(|project| project.project_id)
                .collect::<Vec<_>>(),
            complete
        );

        for invalid in [
            vec!["project-a".to_string()],
            vec!["project-a".to_string(), "project-a".to_string()],
            vec!["project-a".to_string(), "unknown".to_string()],
            vec![
                "project-a".to_string(),
                PRODUCT_RECOVERY_PROJECT_ID.to_string(),
            ],
        ] {
            assert!(complete_visible_project_order(&current, &invalid).is_err());
        }
    }

    fn seed_user_target(paths: &AppPaths, root: &std::path::Path) -> super::ProductStartupTarget {
        ProjectService::new(paths)
            .create(
                "user-project",
                "User",
                root.to_string_lossy(),
                NewProject::default(),
                10,
            )
            .unwrap();
        super::seed_default_project_window(
            paths,
            "user-project",
            root.to_string_lossy().as_ref(),
            SessionKind::Shell,
            LaunchSpec::OptOut,
            11,
        )
        .unwrap();
        ensure_product_startup_target(paths, 12).expect("user target")
    }

    fn seed_exited_exact_claude_target(
        paths: &AppPaths,
        root: &std::path::Path,
    ) -> super::ProductStartupTarget {
        let mut target = seed_user_target(paths, root);
        target.session.kind = SessionKind::Agent;
        target.session.status = SessionStatus::Exited;
        target.session.last_known_generation = Some("exited-generation".into());
        target.session.launch = LaunchSpec::KnownSafe {
            launch_spec_id: "claude".into(),
            params: vec![
                "--resume".into(),
                "10000000-0000-4000-8000-000000000001".into(),
            ],
        };
        store::write_record(
            paths,
            RecordKind::Session,
            &target.session.session_id,
            20,
            &target.session,
        )
        .unwrap();
        target
    }

    fn add_visible_retained_sibling(
        paths: &AppPaths,
        selected: &super::ProductStartupTarget,
    ) -> super::ProductStartupTarget {
        let mut session = selected.session.clone();
        session.session_id = "retained-v2-sibling-session".into();
        session.status = SessionStatus::Unknown;
        session.last_known_generation = None;
        store::write_record(
            paths,
            RecordKind::Session,
            &session.session_id,
            30,
            &session,
        )
        .unwrap();

        let window_id = "retained-v2-sibling-window";
        let tab_id = "retained-v2-sibling-tab";
        let windows = WindowLayoutService::new(paths);
        windows.create_empty(window_id, 30).unwrap();
        let layout = windows
            .open_tab(
                window_id,
                tab_id,
                &session.session_id,
                "Retained sibling",
                false,
                AttentionState::default(),
                31,
            )
            .unwrap();
        store::set_window_project(paths, window_id, &selected.project_id).unwrap();
        ProjectService::new(paths)
            .reorder_windows(
                &selected.project_id,
                &[selected.layout.window_id.clone(), window_id.to_string()],
                32,
            )
            .unwrap();
        super::ProductStartupTarget {
            project_id: selected.project_id.clone(),
            layout,
            tab_id: tab_id.into(),
            session,
            workspace: selected.workspace.clone(),
        }
    }

    #[test]
    fn reused_daemon_protocol_classifies_legacy_and_v2_attach_only_but_not_v3() {
        assert!(ReusedDaemonProtocol::Legacy.is_attach_only());
        assert!(ReusedDaemonProtocol::Version(1).is_attach_only());
        assert!(ReusedDaemonProtocol::Version(2).is_attach_only());
        assert!(
            !ReusedDaemonProtocol::Version(maestro_protocol::DAEMON_PROTOCOL_VERSION)
                .is_attach_only()
        );
        assert!(!ReusedDaemonProtocol::NotReused.is_attach_only());
    }

    #[test]
    fn retained_v2_missing_selected_lists_once_then_exact_attaches_next_persisted_live_target() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let paths = AppPaths::with_base(tmp.path().join("base"));
        let selected = seed_user_target(&paths, tmp.path());
        let sibling = add_visible_retained_sibling(&paths, &selected);
        let selected_before: SessionRecord =
            loaded(&paths, RecordKind::Session, &selected.session.session_id);
        let socket = tmp.path().join("retained-v2-next-live.sock");
        let listener = UnixListener::bind(&socket).unwrap();
        let sibling_id = sibling.session.session_id.clone();
        let expected_attach =
            format!(r#"{{"op":"attach","id":"{sibling_id}","want_raw_output":false}}"#);
        let server_expected_attach = expected_attach.clone();
        let server = std::thread::spawn(move || {
            let (mut stream, _) = listener.accept().unwrap();
            let mut reader = std::io::BufReader::new(stream.try_clone().unwrap());
            let mut requests = Vec::new();

            let mut request = String::new();
            reader.read_line(&mut request).unwrap();
            requests.push(request.trim().to_string());
            assert_eq!(requests[0], r#"{"op":"list_sessions"}"#);
            writeln!(
                stream,
                "{}",
                serde_json::json!({"ev":"sessions","ids":[sibling_id]})
            )
            .unwrap();
            stream.flush().unwrap();

            request.clear();
            reader.read_line(&mut request).unwrap();
            requests.push(request.trim().to_string());
            assert_eq!(requests[1], server_expected_attach);
            writeln!(
                stream,
                "{}",
                serde_json::json!({
                    "ev": "grid",
                    "id": sibling_id,
                    "grid": {"generation": "retained-v2-generation", "revision": 1},
                })
            )
            .unwrap();
            stream.flush().unwrap();

            let mut remainder = String::new();
            reader.read_to_string(&mut remainder).unwrap();
            assert!(
                remainder.is_empty(),
                "unexpected compatibility wire: {remainder}"
            );
            requests
        });
        let mut retained_client = maestro_shell::DaemonClient::connect(&socket).unwrap();

        let (opened, mode) = open_product_startup_target(
            &paths,
            &socket,
            selected.clone(),
            &["sh".into()],
            40,
            false,
            None,
            true,
            Some(&mut retained_client),
        )
        .expect("retained v2 should select the next persisted live target");
        assert_eq!(opened.session.session_id, sibling.session.session_id);
        assert!(matches!(mode, LaunchSessionMode::RetainedAttachOnly(_)));
        drop(retained_client);
        assert_eq!(
            server.join().unwrap(),
            vec![r#"{"op":"list_sessions"}"#.to_string(), expected_attach]
        );
        assert_eq!(
            loaded::<SessionRecord>(&paths, RecordKind::Session, &selected.session.session_id),
            selected_before,
            "missing selected target must remain byte-for-byte unchanged"
        );
        assert!(ProjectService::new(&paths)
            .load(PRODUCT_RECOVERY_PROJECT_ID)
            .unwrap()
            .is_none());
    }

    #[test]
    fn retained_v2_no_persisted_live_target_sends_only_list_and_creates_no_recovery() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let paths = AppPaths::with_base(tmp.path().join("base"));
        let selected = seed_user_target(&paths, tmp.path());
        let session_before: SessionRecord =
            loaded(&paths, RecordKind::Session, &selected.session.session_id);
        let layout_before = WindowLayoutService::new(&paths)
            .load(&selected.layout.window_id)
            .unwrap()
            .unwrap();
        let project_before = ProjectService::new(&paths)
            .load(&selected.project_id)
            .unwrap()
            .unwrap();
        let socket = tmp.path().join("retained-v2-no-live.sock");
        let listener = UnixListener::bind(&socket).unwrap();
        let server = std::thread::spawn(move || {
            let (mut stream, _) = listener.accept().unwrap();
            let mut reader = std::io::BufReader::new(stream.try_clone().unwrap());
            let mut request = String::new();
            reader.read_line(&mut request).unwrap();
            assert_eq!(request.trim(), r#"{"op":"list_sessions"}"#);
            writeln!(stream, "{}", serde_json::json!({"ev":"sessions","ids":[]})).unwrap();
            stream.flush().unwrap();
            let mut remainder = String::new();
            reader.read_to_string(&mut remainder).unwrap();
            assert!(
                remainder.is_empty(),
                "unexpected compatibility wire: {remainder}"
            );
            vec![request.trim().to_string()]
        });
        let mut retained_client = maestro_shell::DaemonClient::connect(&socket).unwrap();

        let error = match open_product_startup_target(
            &paths,
            &socket,
            selected.clone(),
            &["sh".into()],
            40,
            false,
            None,
            true,
            Some(&mut retained_client),
        ) {
            Ok(_) => panic!("retained v2 without a persisted live target must fail closed"),
            Err(error) => error,
        };
        assert_eq!(error.error_kind, "product_startup_failed");
        drop(retained_client);
        assert_eq!(
            server.join().unwrap(),
            vec![r#"{"op":"list_sessions"}"#.to_string()]
        );
        assert_eq!(
            loaded::<SessionRecord>(&paths, RecordKind::Session, &selected.session.session_id),
            session_before
        );
        assert_eq!(
            WindowLayoutService::new(&paths)
                .load(&selected.layout.window_id)
                .unwrap()
                .unwrap(),
            layout_before
        );
        assert_eq!(
            ProjectService::new(&paths)
                .load(&selected.project_id)
                .unwrap()
                .unwrap(),
            project_before
        );
        assert!(ProjectService::new(&paths)
            .load(PRODUCT_RECOVERY_PROJECT_ID)
            .unwrap()
            .is_none());
    }

