    #[test]
    fn missing_persisted_cwd_falls_back_to_existing_workspace_root_without_rewrite() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let paths = AppPaths::with_base(tmp.path().join("base"));
        ensure_product_startup_target(&paths, 1).expect("empty-store seed");
        let fallback = tmp.path().join("fallback");
        std::fs::create_dir(&fallback).unwrap();

        let mut workspace: Workspace =
            loaded(&paths, RecordKind::Workspace, SYSTEM_TERMINAL_WORKSPACE_ID);
        workspace.root = fallback.to_string_lossy().into_owned();
        store::write_record(
            &paths,
            RecordKind::Workspace,
            SYSTEM_TERMINAL_WORKSPACE_ID,
            2,
            &workspace,
        )
        .unwrap();
        let missing = tmp.path().join("missing");
        let mut session: SessionRecord =
            loaded(&paths, RecordKind::Session, SYSTEM_TERMINAL_SESSION_ID);
        session.cwd_resolved = missing.to_string_lossy().into_owned();
        store::write_record(
            &paths,
            RecordKind::Session,
            SYSTEM_TERMINAL_SESSION_ID,
            3,
            &session,
        )
        .unwrap();

        let target = ensure_product_startup_target(&paths, 4).expect("target with stale cwd");
        assert_eq!(product_startup_cwd(&paths, &target).unwrap(), fallback);
        let persisted: SessionRecord =
            loaded(&paths, RecordKind::Session, SYSTEM_TERMINAL_SESSION_ID);
        assert_eq!(persisted.cwd_resolved, missing.to_string_lossy());
    }

