    #[test]
    fn fresh_daemon_recovery_selects_live_and_exact_exited_safe_recipes_once() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let paths = AppPaths::with_base(tmp.path().join("base"));
        let base = seed_user_target(&paths, tmp.path());

        let mut safe = base.clone();
        safe.session.session_id = "safe-live".into();
        safe.session.kind = SessionKind::Agent;
        safe.session.status = SessionStatus::Live;
        safe.session.launch = LaunchSpec::KnownSafe {
            launch_spec_id: "claude".into(),
            params: vec![
                "--resume".into(),
                "10000000-0000-4000-8000-000000000002".into(),
            ],
        };
        let mut exited = safe.clone();
        exited.session.session_id = "safe-exited".into();
        exited.session.status = SessionStatus::Exited;
        let mut exited_latest = exited.clone();
        exited_latest.session.session_id = "safe-exited-latest".into();
        exited_latest.session.launch = LaunchSpec::KnownSafe {
            launch_spec_id: "claude".into(),
            params: vec!["--continue".into()],
        };
        let mut adhoc = safe.clone();
        adhoc.session.session_id = "adhoc-live".into();
        adhoc.session.launch = LaunchSpec::AdHocRedacted {
            argv: vec!["claude".into()],
            redacted: false,
            restart_requires_user: true,
        };
        let duplicate = safe.clone();

        let (candidates, declined) = daemon_loss_recovery_candidates(
            &paths,
            vec![safe, exited, exited_latest, adhoc, duplicate],
            "already-opened",
            &["sh".into()],
        )
        .unwrap();
        assert_eq!(
            candidates
                .iter()
                .map(|target| target.session.session_id.as_str())
                .collect::<Vec<_>>(),
            ["safe-live", "safe-exited"]
        );
        assert_eq!(declined, 2, "duplicate ids are ignored, not double-counted");
    }

    #[test]
    fn fresh_daemon_recovery_restarts_exact_exited_provider_with_v3_absence_authority() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let paths = AppPaths::with_base(tmp.path().join("base"));
        let target = seed_exited_exact_claude_target(&paths, tmp.path());
        let socket = tmp.path().join("fresh-recovery.sock");
        let listener = UnixListener::bind(&socket).unwrap();
        let session_id = target.session.session_id.clone();
        let expected_id = session_id.clone();
        let (release_probe_tx, release_probe_rx) = std::sync::mpsc::channel();
        let (release_server_tx, release_server_rx) = std::sync::mpsc::channel();
        let server = std::thread::spawn(move || {
            let daemon_info = serde_json::json!({
                "ev": "daemon_info",
                "protocol_version": maestro_protocol::DAEMON_PROTOCOL_VERSION,
                "build_version": "fresh-recovery-test",
                "daemon_instance_id": "55555555555545559555555555555555",
                "output_generation_echo": true,
                "generation_conditional_mutations": true,
                "attachment_aware_conditional_kill": true,
                "generation_conditional_start": true,
                "generation_conditional_attach": true,
                "start_operation_ledger": true,
            });
            // Capture the same process identity the production fresh-daemon readiness path carries
            // into the later Absent mutation.
            let (mut stream, _) = listener.accept().unwrap();
            let mut reader = std::io::BufReader::new(stream.try_clone().unwrap());
            let mut request = String::new();
            reader.read_line(&mut request).unwrap();
            assert_eq!(request.trim(), r#"{"op":"daemon_info"}"#);
            writeln!(stream, "{daemon_info}").unwrap();
            stream.flush().unwrap();
            release_probe_rx
                .recv_timeout(std::time::Duration::from_secs(2))
                .expect("test releases readiness connection");
            drop(reader);
            drop(stream);

            let (mut stream, _) = listener.accept().unwrap();
            let mut reader = std::io::BufReader::new(stream.try_clone().unwrap());
            let reserve = loop {
                request.clear();
                reader.read_line(&mut request).unwrap();
                let value: serde_json::Value = serde_json::from_str(&request).unwrap();
                if value["op"] == "daemon_info" {
                    writeln!(stream, "{daemon_info}").unwrap();
                    stream.flush().unwrap();
                    continue;
                }
                break value;
            };
            assert_eq!(reserve["op"], "reserve_start_operation");
            assert_eq!(reserve["id"], expected_id);
            let reserved_token = reserve["operation_token"]
                .as_str()
                .expect("reserved start operation token")
                .to_string();
            writeln!(
                stream,
                "{}",
                serde_json::json!({
                    "ev": "start_operation_reserved",
                    "id": expected_id,
                    "operation_token": reserved_token,
                    "daemon_instance_id": "55555555555545559555555555555555",
                    "outcome": {"status": "reserved"},
                })
            )
            .unwrap();
            stream.flush().unwrap();

            request.clear();
            reader.read_line(&mut request).unwrap();
            let start: serde_json::Value = serde_json::from_str(&request).unwrap();
            assert_eq!(start["op"], "start_session");
            assert_eq!(start["id"], expected_id);
            let command_line = start["args"]
                .as_array()
                .and_then(|args| args.last())
                .and_then(serde_json::Value::as_str)
                .expect("login-shell command line");
            assert!(
                command_line.contains("'claude' '--resume' '10000000-0000-4000-8000-000000000001'")
            );
            assert!(
                start.get("restart_exited").is_none(),
                "v3 conditional absence replaces the retired restart_exited bit"
            );
            assert_eq!(start["conditional_start"]["precondition"]["kind"], "absent");
            assert_eq!(
                start["conditional_start"]["precondition"]["excluded_generation"],
                "exited-generation"
            );
            let operation_token = start["conditional_start"]["operation_token"]
                .as_str()
                .expect("conditional start operation token");
            assert_eq!(operation_token, reserved_token);
            writeln!(
                stream,
                "{}",
                serde_json::json!({
                    "ev": "conditional_session_start",
                    "id": expected_id,
                    "operation_token": operation_token,
                    "daemon_instance_id": "55555555555545559555555555555555",
                    "outcome": {"status": "applied", "generation": "after-reboot"},
                })
            )
            .unwrap();
            stream.flush().unwrap();

            request.clear();
            reader.read_line(&mut request).unwrap();
            let attach: serde_json::Value = serde_json::from_str(&request).unwrap();
            assert_eq!(attach["op"], "attach");
            assert_eq!(attach["expected_session_generation"], "after-reboot");
            assert!(attach["handoff"].is_null());
            writeln!(
                stream,
                "{}",
                serde_json::json!({
                    "ev": "grid",
                    "id": expected_id,
                    "output_generation": attach["output_generation"],
                    "grid": {"generation": "after-reboot", "revision": 1},
                })
            )
            .unwrap();
            stream.flush().unwrap();

            request.clear();
            reader.read_line(&mut request).unwrap();
            let retire: serde_json::Value = serde_json::from_str(&request).unwrap();
            assert_eq!(retire["op"], "retire_start_operation");
            assert_eq!(retire["id"], expected_id);
            assert_eq!(retire["operation_token"], reserved_token);
            assert_eq!(retire["expected"]["state"], "applied");
            assert_eq!(retire["expected"]["generation"], "after-reboot");
            writeln!(
                stream,
                "{}",
                serde_json::json!({
                    "ev": "start_operation_retired",
                    "id": expected_id,
                    "operation_token": reserved_token,
                    "daemon_instance_id": "55555555555545559555555555555555",
                    "outcome": {"status": "retired"},
                })
            )
            .unwrap();
            stream.flush().unwrap();

            release_server_rx
                .recv_timeout(std::time::Duration::from_secs(2))
                .expect("test releases fresh-daemon connection");
        });

        let mut readiness = DaemonClient::connect(&socket).unwrap();
        let fresh_peer = readiness.conditional_start_peer_identity().unwrap();
        release_probe_tx.send(()).unwrap();
        drop(readiness);

        let mode = open_one_product_target(
            &paths,
            &socket,
            &target,
            &["sh".into()],
            ProductRestartAuthority::FreshDaemonRecovery,
            21,
            false,
            Some(&fresh_peer),
        )
        .expect("fresh recovery should complete")
        .expect("exact provider should be selected");
        assert!(matches!(mode, LaunchSessionMode::Started(_)));
        release_server_tx.send(()).unwrap();
        server.join().unwrap();
        let recovered: SessionRecord =
            loaded(&paths, RecordKind::Session, &target.session.session_id);
        assert_eq!(recovered.status, SessionStatus::Live);
        assert_eq!(
            recovered.last_known_generation.as_deref(),
            Some("after-reboot")
        );
    }

    #[test]
    fn all_hidden_and_stashed_topology_uses_hidden_fixed_recovery_without_revive() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let paths = AppPaths::with_base(tmp.path().join("base"));
        ensure_product_startup_target(&paths, 1).expect("stable seed");
        let windows = WindowLayoutService::new(&paths);
        windows
            .set_tab_stashed(SYSTEM_TERMINAL_WINDOW_ID, SYSTEM_TERMINAL_TAB_ID, true, 2)
            .unwrap();
        let projects = ProjectService::new(&paths);
        let mut stable_project = projects.load(SYSTEM_TERMINAL_PROJECT_ID).unwrap().unwrap();
        stable_project.hidden = true;
        store::write_record(
            &paths,
            RecordKind::Project,
            SYSTEM_TERMINAL_PROJECT_ID,
            3,
            &stable_project,
        )
        .unwrap();

        let first = ensure_product_startup_target(&paths, 4).expect("recovery target");
        let second = ensure_product_startup_target(&paths, 5).expect("same recovery target");
        assert_eq!(first.project_id, PRODUCT_RECOVERY_PROJECT_ID);
        assert_eq!(first.layout.window_id, PRODUCT_RECOVERY_WINDOW_ID);
        assert_eq!(first.tab_id, PRODUCT_RECOVERY_TAB_ID);
        assert_eq!(first.session.session_id, PRODUCT_RECOVERY_SESSION_ID);
        assert_eq!(second.layout.window_id, first.layout.window_id);
        assert!(
            projects
                .load(PRODUCT_RECOVERY_PROJECT_ID)
                .unwrap()
                .unwrap()
                .hidden
        );
        assert!(
            projects
                .load(SYSTEM_TERMINAL_PROJECT_ID)
                .unwrap()
                .unwrap()
                .hidden
        );
        assert!(
            windows
                .load(SYSTEM_TERMINAL_WINDOW_ID)
                .unwrap()
                .unwrap()
                .tabs
                .iter()
                .find(|tab| tab.tab_id == SYSTEM_TERMINAL_TAB_ID)
                .unwrap()
                .stashed
        );
        assert_eq!(
            store::load_all::<SessionRecord>(&paths, RecordKind::Session)
                .unwrap()
                .len(),
            2,
            "fixed recovery session must not duplicate"
        );
    }

