            let retire: serde_json::Value = serde_json::from_str(&request).unwrap();
            assert_eq!(retire["op"], "retire_start_operation");
            assert_eq!(retire["id"], expected_id);
            assert_eq!(retire["operation_token"], reserved_token);
            assert_eq!(retire["expected"]["state"], "applied");
